    /* ============================================================
       HELPERS
       ============================================================ */

    function clamp(
        value,
        min,
        max
    ) {

        return Math.max(
            min,
            Math.min(
                max,
                value
            )
        );

    }


    function lerp(
        from,
        to,
        t
    ) {

        return (
            from +
            (
                to -
                from
            ) *
            t
        );

    }


    function finiteNumber(
        value,
        fallback = 0
    ) {

        const number =
            Number(
                value
            );


        return Number.isFinite(
            number
        )
            ? number
            : fallback;

    }


    function integer(
        value,
        fallback = 0
    ) {

        return Math.trunc(
            finiteNumber(
                value,
                fallback
            )
        );

    }


    function random(
        min,
        max
    ) {

        return (
            min +
            Math.random() *
            (
                max -
                min
            )
        );

    }


    function randomInt(
        min,
        max
    ) {

        return Math.floor(
            random(
                min,
                max + 1
            )
        );

    }


    function chance(
        probability
    ) {

        return (
            Math.random() <
            clamp(
                finiteNumber(
                    probability,
                    0
                ),
                0,
                1
            )
        );

    }


    function distanceSquared(
        x1,
        y1,
        x2,
        y2
    ) {

        const dx =
            x2 -
            x1;


        const dy =
            y2 -
            y1;


        return (
            dx * dx +
            dy * dy
        );

    }


    function distance(
        x1,
        y1,
        x2,
        y2
    ) {

        return Math.sqrt(
            distanceSquared(
                x1,
                y1,
                x2,
                y2
            )
        );

    }


    function normalize(
        x,
        y
    ) {

        const length =
            Math.sqrt(
                x * x +
                y * y
            );


        if (
            length <=
            0.000001
        ) {

            return {
                x: 0,
                y: 0
            };

        }


        return {

            x:
                x /
                length,

            y:
                y /
                length

        };

    }


    function safeArray(
        value
    ) {

        return Array.isArray(
            value
        )
            ? value
            : [];

    }


    function uniqueArray(
        value
    ) {

        return [
            ...new Set(
                safeArray(
                    value
                )
            )
        ];

    }


    function deepCloneJSONSafe(
        value
    ) {

        if (
            value ===
            undefined
        ) {

            return undefined;

        }


        try {

            return JSON.parse(
                JSON.stringify(
                    value
                )
            );

        } catch (
            error
        ) {

            console.warn(
                "VEYRA — clone seguro falhou:",
                error
            );


            return value;

        }

    }


    /* ============================================================
       SEED PROCEDURAL

       VILA permanece fixa.

       Outras regiões usam uma seed
       criada por sessão.

       Reentrar na região durante a
       mesma sessão mantém o mapa.

       Reiniciar o jogo cria outra seed.
       ============================================================ */

    function hashStringToSeed(
        value
    ) {

        let hash =
            2166136261;


        const string =
            String(
                value ??
                ""
            );


        for (
            let index = 0;
            index < string.length;
            index += 1
        ) {

            hash ^=
                string.charCodeAt(
                    index
                );


            hash =
                Math.imul(
                    hash,
                    16777619
                );

        }


        return (
            hash >>>
            0
        );

    }


    function createSessionSeed() {

        const source = [

            Date.now(),

            performance?.timeOrigin ||
                0,

            Math.random(),

            navigator?.userAgent ||
                "veyra"

        ].join(
            "|"
        );


        return (
            hashStringToSeed(
                source
            ) ||
            1
        );

    }


    function createSeededRandom(
        seed
    ) {

        let value =
            (
                finiteNumber(
                    seed,
                    1
                ) >>>
                0
            ) ||
            1;


        return function seededRandom() {

            value +=
                0x6D2B79F5;


            let result =
                value;


            result =
                Math.imul(
                    result ^
                    (
                        result >>>
                        15
                    ),
                    result |
                    1
                );


            result ^=
                result +
                Math.imul(
                    result ^
                    (
                        result >>>
                        7
                    ),
                    result |
                    61
                );


            return (
                (
                    result ^
                    (
                        result >>>
                        14
                    )
                ) >>>
                0
            ) /
            4294967296;

        };

    }


    function getAreaSessionSeed(
        areaId,
        salt = "world"
    ) {

        return hashStringToSeed(
            `${state.sessionSeed}|${areaId}|${salt}`
        );

    }


    function getAreaRandom(
        areaId,
        salt = "world"
    ) {

        return createSeededRandom(
            getAreaSessionSeed(
                areaId,
                salt
            )
        );

    }


    function seededRange(
        rng,
        min,
        max
    ) {

        return (
            min +
            rng() *
            (
                max -
                min
            )
        );

    }


    function seededInt(
        rng,
        min,
        max
    ) {

        return Math.floor(
            seededRange(
                rng,
                min,
                max + 1
            )
        );

    }


    /* ============================================================
       COLISÃO / GEOMETRIA
       ============================================================ */

    function rectsOverlap(
        a,
        b
    ) {

        return (

            a.x <
                b.x +
                b.w &&

            a.x +
                a.w >
                b.x &&

            a.y <
                b.y +
                b.h &&

            a.y +
                a.h >
                b.y

        );

    }


    function pointInRect(
        x,
        y,
        rect
    ) {

        return (

            x >=
                rect.x &&

            x <=
                rect.x +
                rect.w &&

            y >=
                rect.y &&

            y <=
                rect.y +
                rect.h

        );

    }


    function circleRectCollision(
        circleX,
        circleY,
        radius,
        rect
    ) {

        const nearestX =
            clamp(
                circleX,
                rect.x,
                rect.x +
                    rect.w
            );


        const nearestY =
            clamp(
                circleY,
                rect.y,
                rect.y +
                    rect.h
            );


        const dx =
            circleX -
            nearestX;


        const dy =
            circleY -
            nearestY;


        return (
            dx * dx +
            dy * dy <=
            radius * radius
        );

    }


    function circleCircleCollision(
        x1,
        y1,
        r1,
        x2,
        y2,
        r2
    ) {

        const radius =
            r1 +
            r2;


        return (
            distanceSquared(
                x1,
                y1,
                x2,
                y2
            ) <=
            radius *
            radius
        );

    }


    /* ============================================================
       OBSTÁCULOS

       collisionShape = "trunk"
       permitirá que copa da árvore
       NÃO vire uma parede gigante.
       ============================================================ */

    function createSolidObstacle(
        config = {}
    ) {

        return {

            id:
                config.id ||
                `obstacle_${Math.random().toString(36).slice(2)}`,


            type:
                config.type ||
                "solid",


            x:
                finiteNumber(
                    config.x
                ),


            y:
                finiteNumber(
                    config.y
                ),


            w:
                Math.max(
                    1,
                    finiteNumber(
                        config.w,
                        20
                    )
                ),


            h:
                Math.max(
                    1,
                    finiteNumber(
                        config.h,
                        20
                    )
                ),


            solid:
                config.solid !==
                false,


            blocksLight:
                Boolean(
                    config.blocksLight
                ),


            collisionShape:
                config.collisionShape ||
                "rect",


            sourceId:
                config.sourceId ||
                null,


            /*
                Utilizado pelo renderer
                de profundidade.
            */
            depthY:
                finiteNumber(
                    config.depthY,
                    finiteNumber(
                        config.y
                    ) +
                    finiteNumber(
                        config.h,
                        20
                    )
                )

        };

    }


    /* ============================================================
       PORTAS

       Porta gira pela dobradiça.

       NÃO encolhe.

       Visual e colisão usam a
       mesma geometria.
       ============================================================ */

    function createDoorRuntime(
        config = {}
    ) {

        const width =
            Math.max(
                20,
                finiteNumber(
                    config.w,
                    72
                )
            );


        const height =
            Math.max(
                20,
                finiteNumber(
                    config.h,
                    26
                )
            );


        return {

            id:
                config.id ||
                `door_${Math.random().toString(36).slice(2)}`,


            buildingId:
                config.buildingId ||
                null,


            houseId:
                config.houseId ||
                null,


            side:
                config.side ||
                "bottom",


            x:
                finiteNumber(
                    config.x
                ),


            y:
                finiteNumber(
                    config.y
                ),


            w:
                width,


            h:
                height,


            centerX:
                finiteNumber(
                    config.x
                ) +
                width /
                2,


            centerY:
                finiteNumber(
                    config.y
                ) +
                height /
                2,


            hinge:
                config.hinge ||
                "left",


            openAmount:
                0,


            targetOpen:
                0,


            angle:
                0,


            maxAngle:
                Math.PI *
                0.48,


            opening:
                false,


            open:
                false,


            autoOpen:
                config.autoOpen !==
                false,


            locked:
                Boolean(
                    config.locked
                )

        };

    }


