    function getCharacterById(
        characterId
    ) {

        return (
            CHARACTERS[
                characterId
            ] ||
            null
        );

    }


    function currentCharacter() {

        return (
            getCharacterById(
                state.player
                    ?.characterId
            ) ||
            CHARACTERS
                .kaelion
        );

    }


    /* ============================================================
       BARRAS DA SELEÇÃO
       ============================================================ */

    const CHARACTER_SELECTION_RANGE =
        Object.freeze({

            hp:
                Object.freeze({

                    min:
                        80,

                    max:
                        160

                }),


            energy:
                Object.freeze({

                    min:
                        90,

                    max:
                        130

                }),


            damage:
                Object.freeze({

                    min:
                        20,

                    max:
                        32

                }),


            defense:
                Object.freeze({

                    min:
                        5,

                    max:
                        21

                }),


            speed:
                Object.freeze({

                    min:
                        120,

                    max:
                        170

                })

        });


    function getCharacterStatBarValue(
        character,
        stat
    ) {

        const range =
            CHARACTER_SELECTION_RANGE[
                stat
            ];


        if (
            !range ||
            !character
        ) {

            return 0;

        }


        const value =
            finiteNumber(
                character[
                    stat
                ],
                range.min
            );


        const span =
            Math.max(
                1,
                range.max -
                    range.min
            );


        return clamp(
            (
                (
                    value -
                    range.min
                ) /
                span
            ) *
            100,
            0,
            100
        );

    }


