    function getStatusPointsGrantedForLevel(
        level
    ) {

        const safeLevel =
            clamp(
                integer(
                    level,
                    1
                ),
                1,
                MAX_LEVEL
            );


        return (
            Math.max(
                0,
                safeLevel -
                    1
            ) *
            STATUS_POINTS_PER_LEVEL
        );

    }


