    function registerItem(
        item
    ) {

        if (
            !item
                ?.id
        ) {

            throw new Error(
                "VEYRA — tentativa de registrar item sem id."
            );

        }


        ITEMS[
            item.id
        ] =
            Object.freeze({

                weight:
                    1,

                value:
                    1,

                sellable:
                    false,

                stackable:
                    true,

                deathLossEligible:
                    false,

                ...item

            });

    }


