    function getSkill(
        characterId,
        key
    ) {

        return (
            CLASS_SKILLS[
                characterId
            ]?.[
                key
            ] ||
            null
        );

    }


    function isSkillUnlocked(
        player,
        key
    ) {

        if (
            !player ||
            !SKILL_UNLOCK_LEVEL[
                key
            ]
        ) {

            return false;

        }


        return (
            integer(
                player.level,
                1
            ) >=
            SKILL_UNLOCK_LEVEL[
                key
            ]
        );

    }


