    /* ============================================================
       BOSS
       ============================================================ */

    function createBoss(
        bossId,
        config = {}
    ) {

        const definition =
            BOSS_REGISTRY[
                bossId
            ];


        if (
            !definition
        ) {

            console.warn(
                `VEYRA — boss desconhecido: ${bossId}`
            );

            return null;

        }


        if (
            isBossDefeated(
                bossId
            )
        ) {

            return null;

        }


        return {

            entityId:
                config.entityId ||
                `boss_${bossId}`,


            id:
                bossId,


            name:
                definition.name,


            subtitle:
                definition.subtitle ||
                "",


            icon:
                definition.icon,


            x:
                finiteNumber(
                    config.x
                ),


            y:
                finiteNumber(
                    config.y
                ),


            spawnX:
                finiteNumber(
                    config.x
                ),


            spawnY:
                finiteNumber(
                    config.y
                ),


            radius:
                definition.radius,


            hp:
                definition.hp,


            maxHp:
                definition.hp,


            damage:
                definition.damage,


            defense:
                definition.defense,


            baseDefense:
                definition.defense,


            speed:
                definition.speed,


            progression:
                Boolean(
                    definition.progression
                ),


            topBar:
                Boolean(
                    definition.topBar
                ),


            centerLocked:
                Boolean(
                    definition.centerLocked
                ),


            requiresConfirmation:
                Boolean(
                    definition.requiresConfirmation
                ),


            state:
                definition.initialState,


            confirmed:
                !definition
                    .requiresConfirmation,


            aggro:
                false,


            dead:
                false,


            phase:
                1,


            phaseTransitionDone:
                false,


            attackCooldown:
                0,


            abilityCooldown:
                1,


            animationTime:
                0,


            hurtAnim:
                0,


            deathTimer:
                0,


            fade:
                1,


            stagger:
                0,


            staggerThreshold:
                definition.stagger
                    ?.threshold ||
                0,


            stunnedTimer:
                0,


            summonTimer:
                definition.summon
                    ? finiteNumber(
                        definition
                            .summon
                            .intervalMin,
                        4
                    )
                    : 0,


            arenaId:
                config.arenaId ||
                null,


            definition

        };

    }


    function addBossIfAlive(
        world,
        bossId,
        config
    ) {

        const boss =
            createBoss(
                bossId,
                config
            );


        if (
            boss
        ) {

            world.bosses.push(
                boss
            );

        }


        return boss;

    }


