    /* ============================================================
       PROTEÇÃO DE CAMINHO

       Vegetação NÃO nasce:
       - em estrada;
       - em porta;
       - em boss;
       - em saída;
       - no spawn;
       - em altar.
       ============================================================ */

    function isPointNearPath(
        x,
        y,
        world,
        margin =
            35
    ) {

        for (
            const path of
            safeArray(
                world.paths
            )
        ) {

            if (

                x >=
                    path.x -
                    margin &&

                x <=
                    path.x +
                    path.w +
                    margin &&

                y >=
                    path.y -
                    margin &&

                y <=
                    path.y +
                    path.h +
                    margin

            ) {

                return true;

            }

        }


        return false;

    }


    function isPointInsideProtectedZone(
        x,
        y,
        world
    ) {

        if (
            isPointNearPath(
                x,
                y,
                world,
                38
            )
        ) {

            return true;

        }


        for (
            const zone of
            safeArray(
                world.zones
            )
        ) {

            if (

                zone.protected &&

                x >=
                    zone.x -
                    35 &&

                x <=
                    zone.x +
                    zone.w +
                    35 &&

                y >=
                    zone.y -
                    35 &&

                y <=
                    zone.y +
                    zone.h +
                    35

            ) {

                return true;

            }

        }


   for (
    const building of
    safeArray(
        world.buildings
    )
) {

    /*
        Espaço lateral.
    */
    const sideMargin =
        145;


    /*
        Espaço atrás da casa.
    */
    const backMargin =
        115;


    /*
        FRENTE DA CASA.

        Como todas as casas da vila
        possuem entrada inferior,
        deixamos uma grande área livre
        para caminho, porta e visão.
    */
    const frontMargin =
        building.doorSide ===
        "bottom"
            ? 270
            : 170;


    if (

        x >=
            building.x -
            sideMargin &&

        x <=
            building.x +
            building.w +
            sideMargin &&

        y >=
            building.y -
            backMargin &&

        y <=
            building.y +
            building.h +
            frontMargin

    ) {

        return true;

    }

}


        for (
            const exit of
            safeArray(
                world.exits
            )
        ) {

            if (
                distance(
                    x,
                    y,
                    exit.x +
                        exit.w /
                        2,
                    exit.y +
                        exit.h /
                        2
                ) <
                130
            ) {

                return true;

            }

        }


        for (
            const spawn of
            Object.values(
                world.spawnPoints ||
                {}
            )
        ) {

            if (
                distance(
                    x,
                    y,
                    spawn.x,
                    spawn.y
                ) <
                150
            ) {

                return true;

            }

        }


        for (
            const boss of
            safeArray(
                world.bosses
            )
        ) {

            if (
                distance(
                    x,
                    y,
                    boss.x,
                    boss.y
                ) <
                320
            ) {

                return true;

            }

        }


        return false;

    }


    /* ============================================================
       AMBIENTE NATURAL
       ============================================================ */

    function populateNaturalEnvironment(
        world,
        options = {}
    ) {

        const rng =
            getAreaRandom(
                world.id,
                options.salt ||
                "nature"
            );


        const treeCount =
            Math.max(
                0,
                integer(
                    options.treeCount,
                    90
                )
            );


        const rockCount =
            Math.max(
                0,
                integer(
                    options.rockCount,
                    25
                )
            );


        const grassCount =
            Math.max(
                0,
                integer(
                    options.grassCount,
                    220
                )
            );


        const flowerCount =
            Math.max(
                0,
                integer(
                    options.flowerCount,
                    30
                )
            );


        const mushroomCount =
            Math.max(
                0,
                integer(
                    options.mushroomCount,
                    0
                )
            );


        const treeVariants =
            options.treeVariants ||
            [
                "oak",
                "old",
                "pine"
            ];


        const flowerColors =
            options.flowerColors ||
            [
                "#d8c36f",
                "#ba9fbd",
                "#d7d1a8"
            ];


        let createdTrees =
            0;


        let attempts =
            0;


        while (
            createdTrees <
                treeCount &&
            attempts <
                treeCount *
                    10
        ) {

            attempts +=
                1;


            const x =
                seededRange(
                    rng,
                    80,
                    world.width -
                        80
                );


            const y =
                seededRange(
                    rng,
                    80,
                    world.height -
                        80
                );


            if (
                isPointInsideProtectedZone(
                    x,
                    y,
                    world
                )
            ) {

                continue;

            }


            const tree =
                createTree({

                    id:
                        `${world.id}_tree_${createdTrees}`,

                    x,

                    y,

                    scale:
                        seededRange(
                            rng,
                            0.82,
                            1.30
                        ),

                    variant:
                        treeVariants[
                            seededInt(
                                rng,
                                0,
                                treeVariants.length -
                                    1
                            )
                        ],

                    canopySeed:
                        rng() *
                        9999,

                    swayOffset:
                        rng() *
                        Math.PI *
                        2

                });


            world.trees.push(
                tree
            );


            createdTrees +=
                1;

        }


        let createdRocks =
            0;


        attempts =
            0;


        while (
            createdRocks <
                rockCount &&
            attempts <
                rockCount *
                    10
        ) {

            attempts +=
                1;


            const x =
                seededRange(
                    rng,
                    70,
                    world.width -
                        70
                );


            const y =
                seededRange(
                    rng,
                    70,
                    world.height -
                        70
                );


            if (
                isPointInsideProtectedZone(
                    x,
                    y,
                    world
                )
            ) {

                continue;

            }


            world.rocks.push(
                createRock({

                    id:
                        `${world.id}_rock_${createdRocks}`,

                    x,

                    y,

                    w:
                        seededRange(
                            rng,
                            28,
                            64
                        ),

                    h:
                        seededRange(
                            rng,
                            22,
                            52
                        ),

                    variant:
                        seededInt(
                            rng,
                            0,
                            4
                        )

                })
            );


            createdRocks +=
                1;

        }


        for (
            let index = 0;
            index < grassCount;
            index += 1
        ) {

            world.grass.push(
                createGrassPatch({

                    x:
                        rng() *
                        world.width,

                    y:
                        rng() *
                        world.height,

                    scale:
                        seededRange(
                            rng,
                            0.55,
                            1.45
                        ),

                    rotation:
                        rng() *
                        Math.PI *
                        2,

                    variant:
                        seededInt(
                            rng,
                            0,
                            4
                        ),

                    swayOffset:
                        rng() *
                        Math.PI *
                        2

                })
            );

        }


        for (
            let index = 0;
            index < flowerCount;
            index += 1
        ) {

            const x =
                rng() *
                world.width;


            const y =
                rng() *
                world.height;


            if (
                isPointInsideProtectedZone(
                    x,
                    y,
                    world
                )
            ) {

                continue;

            }


            world.flowers.push(
                createFlowerPatch({

                    x,

                    y,

                    scale:
                        seededRange(
                            rng,
                            0.65,
                            1.35
                        ),

                    color:
                        flowerColors[
                            seededInt(
                                rng,
                                0,
                                flowerColors.length -
                                    1
                            )
                        ],

                    swayOffset:
                        rng() *
                        Math.PI *
                        2

                })
            );

        }


        for (
            let index = 0;
            index < mushroomCount;
            index += 1
        ) {

            const x =
                rng() *
                world.width;


            const y =
                rng() *
                world.height;


            if (
                isPointInsideProtectedZone(
                    x,
                    y,
                    world
                )
            ) {

                continue;

            }


            world.mushrooms.push(
                createMushroom({

                    id:
                        `${world.id}_mushroom_${index}`,

                    x,

                    y,

                    scale:
                        seededRange(
                            rng,
                            0.55,
                            1.6
                        ),

                    variant:
                        seededInt(
                            rng,
                            0,
                            5
                        ),

                    glow:
                        rng() <
                        (
                            options.mushroomGlowChance ??
                            0.12
                        ),

                    color:
                        options.mushroomColor ||
                        "#77c7c0"

                })
            );

        }

    }


    /* ============================================================
       SPAWN DE INIMIGOS
       ============================================================ */

    function spawnEnemiesNearRoute(
        world,
        options = {}
    ) {

        const speciesList =
            options.species ||
            [
                "wolf"
            ];


        const count =
            Math.max(
                0,
                integer(
                    options.count,
                    12
                )
            );


        const rng =
            getAreaRandom(
                world.id,
                options.salt ||
                "enemies"
            );


        const nodes =
            world.pathNodes;


        if (
            !nodes.length
        ) {

            return;

        }


        for (
            let index = 0;
            index < count;
            index += 1
        ) {

            const node =
                nodes[
                    seededInt(
                        rng,
                        1,
                        Math.max(
                            1,
                            nodes.length -
                                2
                        )
                    )
                ];


            const x =
                clamp(
                    node.x +
                    seededRange(
                        rng,
                        -300,
                        300
                    ),
                    100,
                    world.width -
                        100
                );


            const y =
                clamp(
                    node.y +
                    seededRange(
                        rng,
                        -280,
                        280
                    ),
                    100,
                    world.height -
                        100
                );


            const species =
                speciesList[
                    seededInt(
                        rng,
                        0,
                        speciesList.length -
                            1
                    )
                ];


            const enemy =
                createEnemy(
                    species,
                    {

                        entityId:
                            `${world.id}_enemy_${index}`,

                        x,

                        y

                    }
                );


            if (
                enemy
            ) {

                world.enemies.push(
                    enemy
                );

            }

        }

    }


    /* ============================================================
       RECURSOS PROCEDURAIS
       ============================================================ */

    function addResourceCluster(
        world,
        options = {}
    ) {

        const count =
            Math.max(
                0,
                integer(
                    options.count,
                    8
                )
            );


        const rng =
            getAreaRandom(
                world.id,
                options.salt ||
                `resource_${options.itemId}`
            );


        let created =
            0;


        let attempts =
            0;


        while (
            created <
                count &&
            attempts <
                count *
                    15
        ) {

            attempts +=
                1;


            const x =
                seededRange(
                    rng,
                    120,
                    world.width -
                        120
                );


            const y =
                seededRange(
                    rng,
                    120,
                    world.height -
                        120
                );


            /*
                Recursos ficam perto,
                mas não DENTRO do caminho.
            */
            if (
                isPointNearPath(
                    x,
                    y,
                    world,
                    -18
                ) ||
                isPointInsideProtectedZone(
                    x,
                    y,
                    {
                        ...world,
                        paths:
                            []
                    }
                )
            ) {

                continue;

            }


            world.resources.push(
                createResourceNode({

                    id:
                        `${world.id}_${options.itemId}_${created}`,

                    type:
                        options.type ||
                        "ore",

                    itemId:
                        options.itemId,

                    x,

                    y,

                    radius:
                        options.radius ||
                        28,

                    amount:
                        seededInt(
                            rng,
                            options.minAmount ??
                                1,
                            options.maxAmount ??
                                2
                        ),

                    holdSeconds:
                        options.holdSeconds ||
                        (
                            options.type ===
                            "tree"
                                ? GAME_CONFIG
                                    .treeHarvestSeconds
                                : GAME_CONFIG
                                    .oreHarvestSeconds
                        ),

                    respawnSeconds:
                        options.respawnSeconds ||
                        75

                })
            );


            created +=
                1;

        }

    }


    /* ============================================================
       BARREIRA DE BOSS
       ============================================================ */

    function createBossPassageBarrier(
        world,
        bossId,
        x,
        y,
        orientation =
            "vertical"
    ) {

        if (
            isBossDefeated(
                bossId
            )
        ) {

            return null;

        }


        const barrier =
            orientation ===
            "horizontal"

                ? {

                    id:
                        `${bossId}_passage_barrier`,

                    type:
                        "bossBarrier",

                    bossId,

                    x:
                        x -
                        180,

                    y:
                        y -
                        25,

                    w:
                        360,

                    h:
                        50,

                    shape:
                        "rect",

                    solid:
                        true,

                    blocksLight:
                        false

                }

                : {

                    id:
                        `${bossId}_passage_barrier`,

                    type:
                        "bossBarrier",

                    bossId,

                    x:
                        x -
                        25,

                    y:
                        y -
                        180,

                    w:
                        50,

                    h:
                        360,

                    shape:
                        "rect",

                    solid:
                        true,

                    blocksLight:
                        false

                };


        world.bossBarriers.push(
            barrier
        );


        return barrier;

    }

   function getDecorationCollisionObstacle(
    decoration
) {
    if (
        !decoration ||
        decoration.solid ===
            false
    ) {
        return null;
    }


    /*
        Hitbox aproximada de cada
        móvel/objeto interno.

        NÃO colocamos cama aqui,
        porque a cama já possui
        hitbox própria.
    */
    const sizes = {

        chest:
            [76, 56],

        smallTable:
            [100, 62],

        table:
            [100, 62],

        archiveTable:
            [120, 65],

        herbTable:
            [120, 65],

        chair:
            [42, 42],

        bookshelf:
            [78, 108],

        shelves:
            [82, 108],

        plantShelf:
            [82, 105],

        counter:
            [145, 66],

        crates:
            [95, 68],

        forgeFire:
            [100, 72],

        anvil:
            [74, 52],

        weaponRack:
            [100, 55],

        coalPile:
            [92, 62],

        workbench:
            [135, 72],

        woodStack:
            [105, 64],

        bowRack:
            [95, 52],

        plantPot:
            [45, 45]

    };


    const size =
        sizes[
            decoration.type
        ];


    /*
        Decoração sem tamanho definido
        continua sendo apenas visual.
    */
    if (
        !size
    ) {
        return null;
    }


    const w =
        decoration.w ||
        size[0];


    const h =
        decoration.h ||
        size[1];


    return createSolidObstacle({

        id:
            `${decoration.id || decoration.type}_hitbox`,

        type:
            decoration.type,

        /*
            A maior parte das decorations
            usa x/y como CENTRO.
        */
        x:
            decoration.x -
            w / 2,

        y:
            decoration.y -
            h / 2,

        w,

        h,

        solid:
            true,

        blocksLight:
            false,

        depthY:
            decoration.y +
            h / 2

    });
}

    /* ============================================================
       OBSTÁCULOS
       ============================================================ */

    function rebuildDynamicWorldObstacles(
        world =
            state.world
    ) {

        if (
            !world
        ) {

            return [];

        }


        const obstacles =
            [];

        for (
            const obstacle of
            safeArray(
                world.staticObstacles
            )
        ) {

            obstacles.push(
                obstacle
            );

        }

       /*
    HITBOX DOS MÓVEIS / DECORAÇÕES
    INTERNAS DAS CASAS.
*/
for (
    const decoration of
    safeArray(
        world.decorations
    )
) {
    const obstacle =
        getDecorationCollisionObstacle(
            decoration
        );


    if (
        obstacle
    ) {
        obstacles.push(
            obstacle
        );
    }
}


        for (
            const wall of
            safeArray(
                world.walls
            )
        ) {

            obstacles.push({

                id:
                    wall.id,

                type:
                    wall.type ||
                    "wall",

                shape:
                    "rect",

                x:
                    wall.x,

                y:
                    wall.y,

                w:
                    wall.w,

                h:
                    wall.h,

                solid:
                    true,

                blocksLight:
                    wall.blocksLight !==
                    false,

                depthY:
                    wall.y +
                    wall.h

            });

        }


        for (
            const building of
            safeArray(
                world.buildings
            )
        ) {

            if (
                building.solid
            ) {

                obstacles.push(
                    createSolidObstacle({

                        id:
                            `${building.id}_body`,

                        type:
                            "building",

                        x:
                            building.x,

                        y:
                            building.y,

                        w:
                            building.w,

                        h:
                            building.h,

                        sourceId:
                            building.id,

                        depthY:
                            building.y +
                            building.h,

                        blocksLight:
                            true

                    })
                );

            }

        }


        for (
            const tree of
            safeArray(
                world.trees
            )
        ) {

            if (
                tree.harvested
            ) {

                continue;

            }


            obstacles.push(
                getTreeTrunkObstacle(
                    tree
                )
            );

        }


        for (
            const rock of
            safeArray(
                world.rocks
            )
        ) {

            obstacles.push(
                createSolidObstacle({

                    id:
                        `${rock.id}_body`,

                    type:
                        "rock",

                    x:
                        rock.x -
                        rock.w /
                        2,

                    y:
                        rock.y -
                        rock.h /
                        2,

                    w:
                        rock.w,

                    h:
                        rock.h,

                    sourceId:
                        rock.id,

                    depthY:
                        rock.y +
                        rock.h /
                        2,

                    blocksLight:
                        false

                })
            );

        }


        for (
            const barrier of
            safeArray(
                world.bossBarriers
            )
        ) {

            if (
                !isBossDefeated(
                    barrier.bossId
                )
            ) {

                obstacles.push(
                    barrier
                );

            }

        }


        for (
            const gate of
            safeArray(
                world.gates
            )
        ) {

            if (
                gate.solid
            ) {

                obstacles.push(
                    gate
                );

            }

        }


        world.obstacles =
            obstacles;


        return obstacles;

    }


    /* ============================================================
       POSIÇÃO SEGURA
       ============================================================ */

    function collidesWithObstacleAt(
        x,
        y,
        radius,
        obstacle
    ) {

        if (
            !obstacle ||
            obstacle.solid ===
                false
        ) {

            return false;

        }


        if (
            obstacle.shape ===
            "circle"
        ) {

            return V.circleCircleCollision(

                x,
                y,
                radius,

                obstacle.x,
                obstacle.y,
                obstacle.radius

            );

        }


        return V.circleRectCollision(

            x,
            y,
            radius,

            obstacle

        );

    }


    function isPositionBlocked(
        x,
        y,
        radius,
        world =
            state.world
    ) {

        if (
            !world
        ) {

            return false;

        }

       /*
    LIMITE REAL DO INTERIOR.

    O jogador pode chegar até a porta,
    mas não pode sair andando para o
    vazio fora do cômodo.

    Para sair continua sendo Z.
*/
if (
    world.interior &&
    world.room
) {
    const room =
        world.room;

    const inset =
        8;


    if (
        x - radius <
            room.x +
                inset ||

        x + radius >
            room.x +
                room.w -
                inset ||

        y - radius <
            room.y +
                inset ||

        y + radius >
            room.y +
                room.h -
                inset
    ) {
        return true;
    }
}


        if (

            x -
                radius <
                0 ||

            y -
                radius <
                0 ||

            x +
                radius >
                world.width ||

            y +
                radius >
                world.height

        ) {

            return true;

        }


      for (
    const obstacle of
    safeArray(
        world.obstacles
    )
) {
    if (
        collidesWithObstacleAt(
            x,
            y,
            radius,
            obstacle
        )
    ) {
        return true;
    }
}


/*
    GARANTIA EXTRA DAS PAREDES INTERNAS.
*/
if (
    world.interior
) {
    for (
        const wall of
        safeArray(
            world.walls
        )
    ) {
        if (
            wall.solid !==
                false &&
            V.circleRectCollision(
                x,
                y,
                radius,
                wall
            )
        ) {
            return true;
        }
    }


    /*
        A porta também possui corpo físico
        enquanto estiver fechada.

        Quando abre mais de 68%,
        o jogador consegue atravessar.
    */
    for (
        const door of
        safeArray(
            world.doors
        )
    ) {
        if (
            finiteNumber(
                door.openAmount,
                0
            ) <
            0.68
        ) {
            if (
                V.circleRectCollision(
                    x,
                    y,
                    radius,
                    {
                        x:
                            door.x,

                        y:
                            door.y,

                        w:
                            door.w,

                        h:
                            door.h
                    }
                )
            ) {
                return true;
            }
        }
    }
}

       /*
    PORTAS DO LADO DE FORA.

    Evita o personagem ficar em cima
    da entrada/folha da porta.

    Entrar continua sendo com Z.
*/
if (
    !world.interior
) {
    for (
        const door of
        safeArray(
            world.doors
        )
    ) {
        if (
            !door.buildingId
        ) {
            continue;
        }


        const blocker = {

            x:
                door.x -
                    12,

            y:
                door.y -
                    8,

            w:
                door.w +
                    24,

            h:
                door.h +
                    50

        };


        if (
            V.circleRectCollision(
                x,
                y,
                radius,
                blocker
            )
        ) {
            return true;
        }
    }
}

return false;

    }


    function findSafePosition(
        x,
        y,
        radius,
        world =
            state.world
    ) {

        if (
            !world
        ) {

            return {
                x,
                y
            };

        }


        if (
            !isPositionBlocked(
                x,
                y,
                radius,
                world
            )
        ) {

            return {
                x,
                y
            };

        }


        const step =
            24;


        for (
            let ring = 1;
            ring <= 14;
            ring += 1
        ) {

            for (
                let angleIndex = 0;
                angleIndex < 16;
                angleIndex += 1
            ) {

                const angle =
                    (
                        angleIndex /
                        16
                    ) *
                    Math.PI *
                    2;


                const testX =
                    x +
                    Math.cos(
                        angle
                    ) *
                    step *
                    ring;


                const testY =
                    y +
                    Math.sin(
                        angle
                    ) *
                    step *
                    ring;


                if (
                    !isPositionBlocked(
                        testX,
                        testY,
                        radius,
                        world
                    )
                ) {

                    return {

                        x:
                            testX,

                        y:
                            testY

                    };

                }

            }

        }


        return {

            x:
                clamp(
                    x,
                    radius,
                    world.width -
                        radius
                ),

            y:
                clamp(
                    y,
                    radius,
                    world.height -
                        radius
                )

        };

    }


    /* ============================================================
       INTERIOR
       ============================================================ */

    function createHouseWorld(
        houseId
    ) {

        const config =
            HOUSE_INTERIORS[
                houseId
            ];


        if (
            !config
        ) {

            return null;

        }


        const world =
            createEmptyWorld(
                "village"
            );


        world.id =
            `interior_${houseId}`;


        world.name =
            config.name;


        world.width =
            config.worldWidth;


        world.height =
            config.worldHeight;


        world.interior =
            true;


        world.interiorId =
            houseId;


        world.theme =
            config.theme;


        world.flags
            .minimapSignal =
            false;


        world.flags
            .naturallyLit =
            true;


        world.room = {

            ...config.room

        };


        setSpawn(

            world,

            "default",

            config
                .playerSpawn
                .x,

            config
                .playerSpawn
                .y,

            config
                .playerSpawn
                .facing ||
                "up"

        );


        if (
            config.respawnSpawn
        ) {

            setSpawn(

                world,

                "respawn",

                config
                    .respawnSpawn
                    .x,

                config
                    .respawnSpawn
                    .y,

                config
                    .respawnSpawn
                    .facing ||
                    "down"

            );

        }


        const room =
            config.room;


        const door =
            config.door;


        const thickness =
            28;


        /*
            Parede superior.
        */
        world.walls.push({

            id:
                `${houseId}_wall_top`,

            x:
                room.x,

            y:
                room.y,

            w:
                room.w,

            h:
                thickness,

            blocksLight:
                true

        });


        /*
            Parede esquerda.
        */
        world.walls.push({

            id:
                `${houseId}_wall_left`,

            x:
                room.x,

            y:
                room.y,

            w:
                thickness,

            h:
                room.h,

            blocksLight:
                true

        });


        /*
            Parede direita.
        */
        world.walls.push({

            id:
                `${houseId}_wall_right`,

            x:
                room.x +
                room.w -
                thickness,

            y:
                room.y,

            w:
                thickness,

            h:
                room.h,

            blocksLight:
                true

        });


        /*
            Parede inferior dividida
            corretamente pela porta.
        */
        const bottomY =
            room.y +
            room.h -
            thickness;


        const leftWidth =
            Math.max(
                0,
                door.x -
                room.x
            );


        const rightStart =
            door.x +
            door.w;


        const rightWidth =
            Math.max(

                0,

                room.x +
                    room.w -
                    rightStart

            );


        if (
            leftWidth >
            0
        ) {

            world.walls.push({

                id:
                    `${houseId}_wall_bottom_left`,

                x:
                    room.x,

                y:
                    bottomY,

                w:
                    leftWidth,

                h:
                    thickness,

                blocksLight:
                    true

            });

        }


        if (
            rightWidth >
            0
        ) {

            world.walls.push({

                id:
                    `${houseId}_wall_bottom_right`,

                x:
                    rightStart,

                y:
                    bottomY,

                w:
                    rightWidth,

                h:
                    thickness,

                blocksLight:
                    true

            });

        }


        /*
            Porta física interna.
        */
        const interiorDoor =
            createDoorRuntime({

                id:
                    `${houseId}_interior_door`,

                houseId,

                side:
                    "bottom",

                x:
                    door.x,

                y:
                    door.y,

                w:
                    door.w,

                h:
                    door.h,

                hinge:
                    houseId.length %
                    2 ===
                    0
                        ? "left"
                        : "right",

                autoOpen:
                    true

            });


        world.doors.push(
            interiorDoor
        );


        addExit(
            world,
            {

                id:
                    `${houseId}_exit`,

                x:
                    door.x,

                y:
                    door.y,

                w:
                    door.w,

                h:
                    door.h,

                destination:
                    "outside",

                label:
                    "SAIR",

                interactionKey:
                    "Z",

                requiresInteraction:
                    true,

                unlocked:
                    true

            }
        );


        populateInteriorDecorations(
            world,
            houseId
        );


        rebuildDynamicWorldObstacles(
            world
        );


        return world;

    }


