    /* ============================================================
       HELPER DE CAMINHO 1
       ============================================================ */

    function buildHorizontalProgressionWorld(
        config
    ) {

        const world =
            createEmptyWorld(
                config.areaId
            );


        const route =
            generateLinearRoute(
                world,
                {

                    axis:
                        "x",

                    pointCount:
                        config.pointCount ||
                        7,

                    pathWidth:
                        config.pathWidth ||
                        190,

                    jitter:
                        config.jitter ||
                        340,

                    margin:
                        180,

                    salt:
                        "main_path"

                }
            );


        const start =
            route[
                0
            ];


        const end =
            route[
                route.length -
                    1
            ];


        setSpawn(
            world,
            "default",
            start.x,
            start.y,
            "right"
        );


        setSpawn(
            world,
            "west",
            start.x,
            start.y,
            "right"
        );


        setSpawn(
            world,
            "east",
            end.x,
            end.y,
            "left"
        );


        /*
            Volta.
        */
        addExit(
            world,
            {

                id:
                    `${config.areaId}_back`,

                x:
                    0,

                y:
                    start.y -
                    150,

                w:
                    145,

                h:
                    300,

                destination:
                    config.previousArea,

                destinationSpawn:
                    config.previousSpawn ||
                    "east",

                label:
                    config.backLabel ||
                    "VOLTAR",

                interactionKey:
                    "E",

                unlocked:
                    true

            }
        );


        /*
            Boss de caminho.
        */
        let boss =
            null;


        if (
            config.bossId
        ) {

        /*
    Na primeira estrada,
    o boss aparece um pouco antes.

    Nas outras regiões,
    mantém a posição normal.
*/
const bossIndex =
    config.areaId ===
    "road"
        ? Math.min(
            2,
            route.length -
                2
        )
        : route.length -
            2;


const bossNode =
    route[
        bossIndex
    ];


            boss =
                addBossIfAlive(
                    world,
                    config.bossId,
                    {

                        x:
                            bossNode.x,

                        y:
                            bossNode.y

                    }
                );


            if (
                boss
            ) {

                createBossPassageBarrier(

                    world,

                    config.bossId,

                    bossNode.x +
                        170,

                    bossNode.y,

                    "vertical"

                );

            }

        }


        /*
            Avanço.
        */
        addExit(
            world,
            {

                id:
                    `${config.areaId}_forward`,

                x:
                    world.width -
                    145,

                y:
                    end.y -
                    150,

                w:
                    145,

                h:
                    300,

                destination:
                    config.nextArea,

                destinationSpawn:
                    config.nextSpawn ||
                    "west",

                label:
                    config.forwardLabel ||
                    "SEGUIR",

                interactionKey:
                    "E",

                unlocked:
                    !config.bossId ||
                    isBossDefeated(
                        config.bossId
                    ),

                bossId:
                    config.bossId ||
                    null,

                lockedMessage:
                    config.bossLockedMessage ||
                    "O Guardião ainda bloqueia a passagem."

            }
        );


        populateNaturalEnvironment(
            world,
            config.nature ||
            {}
        );


        spawnEnemiesNearRoute(
            world,
            {

                species:
                    config.enemies ||
                    [
                        "wolf"
                    ],

                count:
                    config.enemyCount ||
                    12,

                salt:
                    "normal_enemies"

            }
        );

       /*
    CAMINHO 1.

    Animais garantidos perto
    do começo da Estrada.
*/
if (
    config.areaId ===
    "road"
) {
    const anchor =
        route[
            Math.min(
                1,
                route.length - 1
            )
        ];


    const guaranteedAnimals = [

        {
            species:
                "wolf",

            dx:
                90,

            dy:
                -70
        },

        {
            species:
                "boar",

            dx:
                190,

            dy:
                70
        },

        {
            species:
                "wolf",

            dx:
                300,

            dy:
                -55
        },

        {
            species:
                "boar",

            dx:
                410,

            dy:
                70
        }

    ];


    guaranteedAnimals.forEach(
        (
            data,
            index
        ) => {

            const enemy =
                createEnemy(
                    data.species,
                    {
                        entityId:
                            `road_animal_${index}`,

                        x:
                            anchor.x +
                            data.dx,

                        y:
                            anchor.y +
                            data.dy
                    }
                );


            if (
                enemy
            ) {
                world.enemies.push(
                    enemy
                );
            }

        }
    );
}
       
        for (
            const resourceConfig of
            config.resources ||
            []
        ) {

            addResourceCluster(
                world,
                resourceConfig
            );

        }


        rebuildDynamicWorldObstacles(
            world
        );


        return world;

    }


