    /* ============================================================
       FRONTEIRA CELESTIAL

       Começa ainda com resquícios
       ROSA do Reino Feérico.

       Depois passa para VERDE normal.

       O boss da Escada está AQUI.
       ============================================================ */

    function buildCelestialFrontierWorld() {

        const world =
            createEmptyWorld(
                "celestialFrontier"
            );


        const route =
            generateLinearRoute(
                world,
                {

                    axis:
                        "y",

                    pointCount:
                        8,

                    pathWidth:
                        185,

                    jitter:
                        430,

                    margin:
                        180,

                    salt:
                        "frontier_route"

                }
            );


        const south =
            route[
                0
            ];


        const north =
            route[
                route.length -
                    1
            ];


        setSpawn(
            world,
            "default",
            south.x,
            south.y,
            "up"
        );


        setSpawn(
            world,
            "south",
            south.x,
            south.y,
            "up"
        );


        setSpawn(
            world,
            "north",
            north.x,
            north.y,
            "down"
        );


        /*
            Gradiente ambiental.

            Parte 4 vai renderizar.
        */
        world.environmentBlend = {

            axis:
                "y",

            /*
                Sul:
                vindo do Reino Feérico.
            */
            fromColor:
                "#865f82",

            /*
                Norte:
                terra verde normal.
            */
            toColor:
                "#4d6b48",

            start:
                world.height,

            end:
                world.height *
                0.46

        };


        addExit(
            world,
            {

                id:
                    "frontier_to_fairy",

                x:
                    south.x -
                    160,

                y:
                    world.height -
                    130,

                w:
                    320,

                h:
                    130,

                destination:
                    "fairyKingdom",

                destinationSpawn:
                    "north",

                label:
                    "VOLTAR AO REINO FEÉRICO"

            }
        );


        const bossNode =
            route[
                route.length -
                    2
            ];


        const guardian =
            addBossIfAlive(
                world,
                "path_guardian",
                {

                    x:
                        bossNode.x,

                    y:
                        bossNode.y

                }
            );


        if (
            guardian
        ) {

            createBossPassageBarrier(

                world,

                "path_guardian",

                bossNode.x,

                bossNode.y -
                    165,

                "horizontal"

            );

        }


        addExit(
            world,
            {

                id:
                    "frontier_to_stair",

                x:
                    north.x -
                    170,

                y:
                    0,

                w:
                    340,

                h:
                    130,

                destination:
                    "celestialStair",

                destinationSpawn:
                    "south",

                label:
                    "SUBIR A ESCADA CELESTIAL",

                unlocked:
                    isBossDefeated(
                        "path_guardian"
                    ),

                bossId:
                    "path_guardian",

                lockedMessage:
                    "O Guardião da Escada ainda impede a ascensão."

            }
        );


        populateNaturalEnvironment(
            world,
            {

                salt:
                    "frontier_nature",

                treeCount:
                    105,

                rockCount:
                    31,

                grassCount:
                    350,

                flowerCount:
                    62,

                mushroomCount:
                    12,

                treeVariants: [
                    "fairy",
                    "oak",
                    "birch"
                ],

                flowerColors: [
                    "#e4a5cf",
                    "#b6d38e",
                    "#d5c77c",
                    "#a8b9df"
                ]

            }
        );


        spawnEnemiesNearRoute(
            world,
            {

                species: [
                    "wolf",
                    "thornling",
                    "bat"
                ],

                count:
                    17,

                salt:
                    "frontier_enemies"

            }
        );


        rebuildDynamicWorldObstacles(
            world
        );


        return world;

    }


    /* ============================================================
       ESCADA CELESTIAL

       SEM BOSS AQUI.

       O boss já foi enfrentado
       na Fronteira.

       Barreiras laterais impedem
       andar para fora da escada.
       ============================================================ */

    function buildCelestialStairWorld() {

        const world =
            createEmptyWorld(
                "celestialStair"
            );


        const pathX =
            590;


        const pathWidth =
            420;


        addPathRect(
            world,
            {

                id:
                    "celestial_stair_main",

                x:
                    pathX,

                y:
                    0,

                w:
                    pathWidth,

                h:
                    world.height,

                style:
                    "celestialStair"

            }
        );


        setSpawn(
            world,
            "default",
            800,
            3440,
            "up"
        );


        setSpawn(
            world,
            "south",
            800,
            3440,
            "up"
        );


        setSpawn(
            world,
            "north",
            800,
            160,
            "down"
        );


        /*
            Barreiras laterais.

            Não é possível "voar"
            andando para fora.
        */
        world.walls.push(

            {

                id:
                    "celestial_left_boundary",

                type:
                    "skyBoundary",

                x:
                    0,

                y:
                    0,

                w:
                    pathX,

                h:
                    world.height,

                blocksLight:
                    false

            },


            {

                id:
                    "celestial_right_boundary",

                type:
                    "skyBoundary",

                x:
                    pathX +
                    pathWidth,

                y:
                    0,

                w:
                    world.width -
                    (
                        pathX +
                        pathWidth
                    ),

                h:
                    world.height,

                blocksLight:
                    false

            }

        );


        addExit(
            world,
            {

                id:
                    "stair_to_frontier",

                x:
                    620,

                y:
                    world.height -
                    120,

                w:
                    360,

                h:
                    120,

                destination:
                    "celestialFrontier",

                destinationSpawn:
                    "north",

                label:
                    "DESCER PARA A FRONTEIRA"

            }
        );


        addExit(
            world,
            {

                id:
                    "stair_to_sky_one",

                x:
                    620,

                y:
                    0,

                w:
                    360,

                h:
                    120,

                destination:
                    "skyOne",

                destinationSpawn:
                    "south",

                label:
                    "ALCANÇAR O CÉU"

            }
        );


        /*
            Degraus.
        */
        for (
            let index = 0;
            index < 48;
            index += 1
        ) {

            world.decorations.push({

                type:
                    "celestialStep",

                x:
                    800,

                y:
                    80 +
                    index *
                    72,

                w:
                    380,

                index

            });

        }


        /*
            Nuvens ao lado.
        */
        const rng =
            getAreaRandom(
                "celestialStair",
                "clouds"
            );


        for (
            let index = 0;
            index < 72;
            index += 1
        ) {

            world.ambient.push({

                type:
                    "cloud",

                x:
                    rng() <
                    0.5
                        ? seededRange(
                            rng,
                            80,
                            510
                        )
                        : seededRange(
                            rng,
                            1090,
                            1520
                        ),

                y:
                    rng() *
                    world.height,

                scale:
                    seededRange(
                        rng,
                        0.6,
                        1.6
                    ),

                drift:
                    seededRange(
                        rng,
                        4,
                        14
                    ),

                phase:
                    rng() *
                    Math.PI *
                    2

            });

        }


        rebuildDynamicWorldObstacles(
            world
        );


        return world;

    }


