    function updateVoidBlinkEnemy(
        enemy,
        dt
    ) {
        const player =
            state.player;

        if (
            !player
        ) {
            return;
        }

        const dist =
            distance(
                enemy.x,
                enemy.y,
                player.x,
                player.y
            );

        if (
            enemy.abilityCooldown <=
                0 &&
            dist >=
                160 &&
            dist <=
                430
        ) {
            const angle =
                Math.atan2(
                    player.y -
                        enemy.y,
                    player.x -
                        enemy.x
                );

            const side =
                chance(
                    0.5
                )
                    ? 1
                    : -1;

            const x =
                player.x -
                Math.cos(
                    angle
                ) *
                    95 +
                Math.cos(
                    angle +
                    Math.PI /
                        2
                ) *
                    55 *
                    side;

            const y =
                player.y -
                Math.sin(
                    angle
                ) *
                    95 +
                Math.sin(
                    angle +
                    Math.PI /
                        2
                ) *
                    55 *
                    side;

            const safe =
                findSafePosition(
                    x,
                    y,
                    enemy.radius,
                    state.world
                );

            spawnTransientEffect(
                "voidBlinkOut",
                enemy.x,
                enemy.y,
                {
                    duration:
                        0.35
                }
            );

            enemy.x =
                safe.x;

            enemy.y =
                safe.y;

            spawnTransientEffect(
                "voidBlinkIn",
                enemy.x,
                enemy.y,
                {
                    duration:
                        0.35
                }
            );

            enemy.abilityCooldown =
                3.1;

            enemy.attackCooldown =
                0.35;

            return;
        }

        updateBasicMeleeEnemy(
            enemy,
            dt
        );
    }


    /* ============================================================
       BOSSES DE CAMINHO
       ============================================================ */

    function getNearbyUnconfirmedBoss() {
        const player =
            state.player;

        const world =
            state.world;

        if (
            !player ||
            !world
        ) {
            return null;
        }

        let nearest =
            null;

        let nearestDistance =
            Infinity;

        for (
            const boss of
            safeArray(
                world.bosses
            )
        ) {
            if (
                boss.dead ||
                boss.confirmed
            ) {
                continue;
            }

            const definition =
                BOSS_REGISTRY[
                    boss.id
                ];

            if (
                !definition
                    ?.requiresConfirmation
            ) {
                continue;
            }

            const dist =
                distance(
                    player.x,
                    player.y,
                    boss.x,
                    boss.y
                );

            if (
                dist <=
                    GAME_CONFIG
                        .bossConfirmationDistance &&
                dist <
                    nearestDistance
            ) {
                nearest =
                    boss;

                nearestDistance =
                    dist;
            }
        }

        return nearest;
    }


    function openBossConfirmation(
        boss
    ) {
        if (
            !boss ||
            boss.dead ||
            !BOSS_REGISTRY[
                boss.id
            ]?.requiresConfirmation
        ) {
            return false;
        }

        registerBossDiscovered(
            boss.id
        );

        state.battle = {
            type:
                "bossConfirmation",

            bossId:
                boss.id,

            boss,

            title:
                boss.name,

            subtitle:
                boss.subtitle ||
                "",

            acceptLabel:
                "ACEITAR",

            retreatLabel:
                "RECUAR"
        };

        return true;
    }


    function acceptBossFight() {
        const battle =
            state.battle;

        const boss =
            battle
                ?.boss;

        if (
            !battle ||
            battle.type !==
                "bossConfirmation" ||
            !boss ||
            boss.dead
        ) {
            return false;
        }

        /*
            Salva ANTES de começar a luta.
            Assim DESISTIR após morrer
            volta para um ponto seguro.
        */
        saveGame({
            silent:
                true,

            safe:
                true
        });

        state.battle =
            null;

        boss.confirmed =
            true;

        boss.state =
            BOSS_STATE
                .CONFIRMED;

        boss.aggro =
            true;

        boss.attackCooldown =
            0.65;

        boss.abilityCooldown =
            1.4;

        state.bossBarTarget =
            boss;

        spawnTransientEffect(
            "bossAwaken",
            boss.x,
            boss.y,
            {
                duration:
                    0.9,

                bossId:
                    boss.id,

                radius:
                    boss.radius *
                    1.8
            }
        );

        return true;
    }


    function retreatBossFight() {
        const battle =
            state.battle;

        const boss =
            battle
                ?.boss;

        if (
            !battle ||
            battle.type !==
                "bossConfirmation"
        ) {
            return false;
        }

        if (
            boss &&
            !boss.dead
        ) {
            boss.confirmed =
                false;

            boss.aggro =
                false;

            boss.state =
                BOSS_STATE
                    .NEUTRAL;

            boss.attackCooldown =
                0;

            boss.abilityCooldown =
                0;

            boss.x =
                boss.spawnX;

            boss.y =
                boss.spawnY;
        }

        state.battle =
            null;

        state.bossBarTarget =
            null;

        return true;
    }


    function activateBossCombat(
        boss
    ) {
        if (
            !boss ||
            boss.dead ||
            !canBossBecomeAggressive(
                boss
            )
        ) {
            return false;
        }

        boss.state =
            BOSS_STATE
                .COMBAT;

        boss.aggro =
            true;

        state.bossBarTarget =
            boss;

        registerBossDiscovered(
            boss.id
        );

        return true;
    }


    function chaseBossPlayer(
        boss,
        dt,
        multiplier = 1,
        stopRange = null
    ) {
        const player =
            state.player;

        if (
            !player ||
            boss.centerLocked
        ) {
            return false;
        }

        const dist =
            distance(
                boss.x,
                boss.y,
                player.x,
                player.y
            );

        const range =
            stopRange ??
            (
                boss.radius +
                player.radius +
                25
            );

        if (
            dist <=
            range
        ) {
            return false;
        }

        const direction =
            normalize(
                player.x -
                    boss.x,
                player.y -
                    boss.y
            );

        return moveCircleWithCollision(
            boss,

            direction.x *
                boss.speed *
                multiplier *
                dt,

            direction.y *
                boss.speed *
                multiplier *
                dt,

            boss.radius,

            state.world
        );
    }


    function bossBasicMelee(
        boss,
        multiplier = 1,
        cooldown = 1.1
    ) {
        const player =
            state.player;

        if (
            !player
        ) {
            return false;
        }

        const range =
            boss.radius +
            player.radius +
            28;

        if (
            distance(
                boss.x,
                boss.y,
                player.x,
                player.y
            ) >
                range ||
            boss.attackCooldown >
                0
        ) {
            return false;
        }

        applyDamageToPlayer(
            boss.damage *
                multiplier,
            {
                boss
            }
        );

        boss.attackCooldown =
            cooldown;

        spawnTransientEffect(
            "bossMelee",
            player.x,
            player.y,
            {
                duration:
                    0.38,

                bossId:
                    boss.id
            }
        );

        return true;
    }


    function fireRadialBossProjectiles(
        boss,
        count,
        options = {}
    ) {
        for (
            let index = 0;
            index < count;
            index += 1
        ) {
            const angle =
                (
                    index /
                    count
                ) *
                Math.PI *
                2 +
                finiteNumber(
                    options.rotation,
                    0
                );

            createProjectile({
                owner:
                    "enemy",

                source:
                    boss,

                x:
                    boss.x,

                y:
                    boss.y,

                dx:
                    Math.cos(
                        angle
                    ),

                dy:
                    Math.sin(
                        angle
                    ),

                speed:
                    options.speed ||
                    210,

                radius:
                    options.radius ||
                    8,

                damage:
                    boss.damage *
                    finiteNumber(
                        options.multiplier,
                        0.55
                    ),

                color:
                    options.color ||
                    boss.definition
                        ?.aura ||
                    "#aaa",

                type:
                    options.type ||
                    "bossOrb",

                life:
                    options.life ||
                    3,

                phaseCompatible:
                    options.phaseCompatible !==
                    false
            });
        }
    }


    function updateStandardBossAI(
        boss,
        dt
    ) {
        if (
            bossBasicMelee(
                boss
            )
        ) {
            return;
        }

        chaseBossPlayer(
            boss,
            dt
        );
    }


    function updateRoadGuardianAI(
        boss,
        dt
    ) {
        const player =
            state.player;

        if (
            !player
        ) {
            return;
        }

        if (
            boss.specialState ===
            "roadChargeWindup"
        ) {
            boss.specialTimer -=
                dt;

            if (
                boss.specialTimer <=
                0
            ) {
                boss.specialState =
                    "roadCharge";

                boss.specialTimer =
                    0.42;
            }

            return;
        }

        if (
            boss.specialState ===
            "roadCharge"
        ) {
            boss.specialTimer -=
                dt;

            const moved =
                moveCircleWithCollision(
                    boss,

                    boss.velocityX *
                        dt,

                    boss.velocityY *
                        dt,

                    boss.radius,

                    state.world
                );

            if (
                circleCircleCollision(
                    boss.x,
                    boss.y,
                    boss.radius,

                    player.x,
                    player.y,
                    player.radius
                )
            ) {
                applyDamageToPlayer(
                    boss.damage *
                        1.35,
                    {
                        boss
                    }
                );

                boss.specialTimer =
                    0;
            }

            if (
                !moved ||
                boss.specialTimer <=
                    0
            ) {
                boss.specialState =
                    null;
            }

            return;
        }

        const dist =
            distance(
                boss.x,
                boss.y,
                player.x,
                player.y
            );

        if (
            boss.abilityCooldown <=
                0 &&
            dist >=
                150 &&
            dist <=
                420
        ) {
            const direction =
                normalize(
                    player.x -
                        boss.x,
                    player.y -
                        boss.y
                );

            boss.velocityX =
                direction.x *
                310;

            boss.velocityY =
                direction.y *
                310;

            boss.specialState =
                "roadChargeWindup";

            boss.specialTimer =
                0.72;

            boss.abilityCooldown =
                3.2;

            spawnTransientEffect(
                "bossChargeTelegraph",
                boss.x,
                boss.y,
                {
                    duration:
                        0.72,

                    targetX:
                        player.x,

                    targetY:
                        player.y
                }
            );

            return;
        }

        if (
            bossBasicMelee(
                boss,
                1,
                1.05
            )
        ) {
            return;
        }

        chaseBossPlayer(
            boss,
            dt,
            0.95
        );
    }


