    function updateMiguelQuestObjective(
        stage,
        text
    ) {
        const quest =
            state.player
                ?.miguelQuest;

        if (
            !quest
        ) {
            return false;
        }

        quest.stage =
            stage;

        quest.trackerObjective =
            String(
                text ||
                ""
            );

        quest.objectiveRevision =
            integer(
                quest
                    .objectiveRevision,
                0
            ) +
            1;

        quest.trackerVisible =
            stage !==
            MIGUEL_QUEST_STAGE
                .COMPLETE;

        return true;
    }


    function interactWithMiguel() {
        const player =
            state.player;

        const quest =
            player
                ?.miguelQuest;

        if (
            !player ||
            !quest
        ) {
            return false;
        }

        quest.miguelFound =
            true;

        if (
            getDashVersion(
                player
            ) <
            1
        ) {
            startDialogue(
                [
                    "Você ainda não está preparado.",
                    "Volte quando seus passos forem mais rápidos que seus olhos."
                ],
                {
                    speaker:
                        "MIGUEL"
                }
            );

            return true;
        }

        quest.dashV1SeenByMiguel =
            true;

        if (
            !quest.missionAccepted &&
            !quest.completed
        ) {
            quest.missionAvailable =
                true;

            quest.stage =
                MIGUEL_QUEST_STAGE
                    .AVAILABLE;

            state.battle = {
                type:
                    "miguelQuestConfirmation",

                title:
                    "A PROVAÇÃO DO VAZIO",

                subtitle:
                    "Aceitar esta missão revelará uma trilha opcional.",

                acceptLabel:
                    "ACEITAR",

                retreatLabel:
                    "RECUAR"
            };

            return true;
        }

        if (
            quest.completed
        ) {
            startDialogue(
                [
                    "Agora seus passos atravessam o próprio espaço.",
                    "Não desperdice aquilo que conquistou."
                ],
                {
                    speaker:
                        "MIGUEL"
                }
            );

            return true;
        }

        if (
            quest.fragmentCollected &&
            !quest.fragmentDelivered
        ) {
            return deliverVoidFragmentToMiguel();
        }

        startDialogue(
            [
                `Reúna ${VOID_MISSION_CONFIG.shadowEssenceRequired} Essências Sombrias no Labirinto.`,
                "A Chave Obscura está escondida no Caminho 2."
            ],
            {
                speaker:
                    "MIGUEL"
            }
        );

        return true;
    }


    function acceptMiguelQuest() {
        const player =
            state.player;

        const quest =
            player
                ?.miguelQuest;

        if (
            !player ||
            !quest ||
            state.battle
                ?.type !==
            "miguelQuestConfirmation"
        ) {
            return false;
        }

        if (
            getDashVersion(
                player
            ) <
            1
        ) {
            state.battle =
                null;

            return false;
        }

        state.battle =
            null;

        quest.missionAvailable =
            false;

        quest.missionAccepted =
            true;

        updateMiguelQuestObjective(
            MIGUEL_QUEST_STAGE
                .FIND_DARK_KEY,

            `Colete ${VOID_MISSION_CONFIG.shadowEssenceRequired} Essências Sombrias no Labirinto e encontre a Chave Obscura no Caminho 2.`
        );

        const frontier =
            state.sessionWorldCache
                ?.celestialFrontier;

        if (
            frontier &&
            typeof V
                .placeDarkKeyInFrontier ===
                "function"
        ) {
            V.placeDarkKeyInFrontier(
                frontier
            );
        }

        pushNotification(
            "MISSÃO ACEITA",
            "A PROVAÇÃO DO VAZIO",
            "special",
            2.5
        );

        saveGame({
            silent:
                true
        });

        return true;
    }


    function declineMiguelQuest() {
        if (
            state.battle
                ?.type !==
            "miguelQuestConfirmation"
        ) {
            return false;
        }

        state.battle =
            null;

        return true;
    }


    function deliverVoidFragmentToMiguel() {
        const player =
            state.player;

        const quest =
            player
                ?.miguelQuest;

        if (
            !player ||
            !quest ||
            !quest.fragmentCollected ||
            quest.fragmentDelivered ||
            getRealItemCount(
                "fragmentoVazio",
                player
            ) <=
            0
        ) {
            return false;
        }

        removeItem(
            "fragmentoVazio",
            1,
            player
        );

        quest.fragmentDelivered =
            true;

        quest.completed =
            true;

        updateMiguelQuestObjective(
            MIGUEL_QUEST_STAGE
                .COMPLETE,
            ""
        );

        player.abilities.dashV1 =
            true;

        player.abilities.dashV2 =
            true;

        spawnTransientEffect(
            "dashV2Unlock",
            player.x,
            player.y,
            {
                duration:
                    1.5,

                radius:
                    120,

                color:
                    "#76528b"
            }
        );

        startDialogue(
            [
                "Então era verdade... o Fragmento do Vazio ainda existe.",
                "Seu Dash rompe o vento.",
                "Com isto... ele poderá romper o próprio espaço.",
                "Prepare-se."
            ],
            {
                speaker:
                    "MIGUEL",

                onComplete:
                    () => {
                        pushNotification(
                            "DASH V2 DESPERTADO",
                            "O Passo do Vazio substituiu o Dash V1.",
                            "special",
                            4
                        );
                    }
            }
        );

        saveGame({
            silent:
                true
        });

        return true;
    }


    /* ============================================================
       NPC
       ============================================================ */

    function openShopPanel(
        vendor
    ) {
        state.activePanel = {
            type:
                vendor ===
                    "borin"
                    ? "forge"
                    : "shop",

            vendor,

            mode:
                "buy"
        };

        state.shopNPC =
            vendor;

        return true;
    }


    function closeActivePanel() {
        state.activePanel =
            null;

        state.shopNPC =
            null;

        return true;
    }


    function interactWithNPC(
        npc
    ) {
        if (
            !npc ||
            !state.player
        ) {
            return false;
        }

        if (
            npc.id ===
            "miguel"
        ) {
            return interactWithMiguel();
        }

        if (
            npc.id ===
            "bran"
        ) {
            return interactBasicQuest(
                "wood"
            );
        }

        if (
            npc.id ===
            "borin"
        ) {
            const quest =
                state.player
                    .quest
                    ?.coal;

            if (
                quest &&
                !quest.rewarded
            ) {
                return interactBasicQuest(
                    "coal"
                );
            }

            return openShopPanel(
                "borin"
            );
        }

        if (
            npc.id ===
                "doran" ||
            npc.vendor ===
                "doran"
        ) {
            return openShopPanel(
                "doran"
            );
        }

        const lines =
            NPC_DIALOGUES[
                npc.dialogueId ||
                npc.id
            ] ||
            [
                "A Quietude tornou as palavras mais difíceis de guardar."
            ];

        return startDialogue(
            lines,
            {
                speaker:
                    npc.name
            }
        );
    }


    /* ============================================================
       HOLD E
       ============================================================ */

    function beginHoldInteraction(
        type,
        target,
        duration
    ) {
        if (
            !target ||
            !state.player ||
            isPlayerControlBlocked()
        ) {
            return false;
        }

        state.holdAction = {
            type,

            target,

            elapsed:
                0,

            duration:
                Math.max(
                    0.1,
                    finiteNumber(
                        duration,
                        1
                    )
                ),

            completed:
                false
        };

        return true;
    }


    function handlePrimaryHoldInteractionEnd() {
        if (
            state.holdAction &&
            !state.holdAction
                .completed
        ) {
            state.holdAction =
                null;

            return true;
        }

        return false;
    }


    function getHoldActionProgress() {
        if (
            !state.holdAction
        ) {
            return null;
        }

        return clamp(
            state.holdAction
                .elapsed /
            Math.max(
                0.01,
                state.holdAction
                    .duration
            ),
            0,
            1
        );
    }


    function harvestTree(
        tree
    ) {
        const player =
            state.player;

        if (
            !player ||
            !tree ||
            tree.harvested
        ) {
            return false;
        }

        const amount =
            Math.max(
                1,
                integer(
                    tree.resourceAmount,
                    1
                )
            );

        if (
            !canCarryItem(
                "madeira",
                amount,
                player
            )
        ) {
            pushNotification(
                "MOCHILA CHEIA",
                "Não há espaço para a madeira.",
                "warning",
                1.8
            );

            return false;
        }

        if (
            !addItem(
                "madeira",
                amount,
                player
            )
        ) {
            return false;
        }

        tree.harvested =
            true;

      tree.respawnTimer =
    random(
        25,
        40
    );
        /*
            Não existe mais gasto de Magia.
            Coletar aumenta levemente a Exaustão.
        */
        changeExhaustion(
            1.15,
            player
        );

        rebuildDynamicWorldObstacles(
            state.world
        );

        spawnTransientEffect(
            "woodHarvest",
            tree.x,
            tree.y,
            {
                duration:
                    0.55
            }
        );

        pushNotification(
            "MADEIRA",
            `+${amount}`,
            "item",
            1.2
        );

        return true;
    }


    function harvestResource(
        resource
    ) {
        const player =
            state.player;

        if (
            !player ||
            !resource ||
            resource.harvested
        ) {
            return false;
        }

        if (
            !ITEMS[
                resource.itemId
            ]
        ) {
            return false;
        }

        if (
            !canCarryItem(
                resource.itemId,
                resource.amount,
                player
            )
        ) {
            pushNotification(
                "MOCHILA CHEIA",
                "Não há espaço para este material.",
                "warning",
                1.8
            );

            return false;
        }

        if (
            !addItem(
                resource.itemId,
                resource.amount,
                player
            )
        ) {
            return false;
        }

        resource.harvested =
            true;

        resource.respawnTimer =
            resource.respawnSeconds;

        changeExhaustion(
            resource.type ===
                "tree"
                ? 1.1
                : 1.35,

            player
        );

        pushNotification(
            ITEMS[
                resource.itemId
            ].name
                .toUpperCase(),

            `+${resource.amount}`,

            "item",

            1.2
        );

        return true;
    }


    function updateHoldInteraction(
        dt
    ) {
        const action =
            state.holdAction;

        const player =
            state.player;

        if (
            !action ||
            !player
        ) {
            return;
        }

        /*
            Soltar E cancela.
        */
        if (
            !state.keys.has(
                "KeyE"
            )
        ) {
            state.holdAction =
                null;

            return;
        }

        const target =
            action.target;

        if (
            !target
        ) {
            state.holdAction =
                null;

            return;
        }

        const targetY =
            target.y +
            (
                action.type ===
                    "tree"
                    ? 16
                    : 0
            );

        if (
            distance(
                player.x,
                player.y,
                target.x,
                targetY
            ) >
            100
        ) {
            state.holdAction =
                null;

            return;
        }

        action.elapsed +=
            dt;

        if (
            action.elapsed <
            action.duration
        ) {
            return;
        }

        action.completed =
            true;

        let success =
            false;

        if (
            action.type ===
            "tree"
        ) {
            success =
                harvestTree(
                    target
                );
        }

        if (
            action.type ===
            "resource"
        ) {
            success =
                harvestResource(
                    target
                );
        }

        if (
            action.type ===
            "darkKey"
        ) {
            success =
                collectDarkKey(
                    player
                );

            if (
                success
            ) {
                target.collected =
                    true;

                updateMiguelQuestObjective(
                    MIGUEL_QUEST_STAGE
                        .RETURN_PATH_ONE,

                    "A Chave Obscura foi despertada. Procure a passagem secreta no Caminho 1."
                );

                pushNotification(
                    "CHAVE OBSCURA",
                    "A chave foi adicionada à Mochila.",
                    "special",
                    2.4
                );
            }
        }

        state.holdAction =
            null;

        return success;
    }


    function updateTreeRespawns(
        dt
    ) {
        const world =
            state.world;

        if (
            !world
        ) {
            return;
        }

        let changed =
            false;

        for (
            const tree of
            safeArray(
                world.trees
            )
        ) {
            if (
                !tree.harvested
            ) {
                continue;
            }

            tree.respawnTimer -=
                dt;

          if (
    tree.respawnTimer <=
    0
) {
    tree.harvested =
        false;

    tree.respawnTimer =
        0;

    changed =
        true;
}
        }

        if (
            changed
        ) {
            rebuildDynamicWorldObstacles(
                world
            );
        }
    }


    function updateResourceRespawns(
        dt
    ) {
        const world =
            state.world;

        if (
            !world
        ) {
            return;
        }

        for (
            const resource of
            safeArray(
                world.resources
            )
        ) {
            if (
                !resource.harvested
            ) {
                continue;
            }

            resource.respawnTimer -=
                dt;

            if (
                resource.respawnTimer <=
                0
            ) {
                resource.harvested =
                    false;

                resource.respawnTimer =
                    0;
            }
        }
    }


    /* ============================================================
       PORTAS
       ============================================================ */

    function updateDoorAnimations(
        dt
    ) {
        const player =
            state.player;

        const world =
            state.world;

        if (
            !player ||
            !world
        ) {
            return;
        }

        for (
            const door of
            safeArray(
                world.doors
            )
        ) {
            const x =
                finiteNumber(
                    door.centerX,
                    door.x +
                        door.w /
                            2
                );

            const y =
                finiteNumber(
                    door.centerY,
                    door.y +
                        door.h /
                            2
                );

            const dist =
                distance(
                    player.x,
                    player.y,
                    x,
                    y
                );

            if (
                door.autoOpen &&
                !door.locked
            ) {
                if (
                    dist <=
                    GAME_CONFIG
                        .doorOpenDistance
                ) {
                    door.targetOpen =
                        1;
                } else if (
                    dist >=
                    GAME_CONFIG
                        .doorCloseDistance
                ) {
                    door.targetOpen =
                        0;
                }
            }

            const step =
                GAME_CONFIG
                    .doorAnimationSpeed *
                dt;

            if (
                door.openAmount <
                door.targetOpen
            ) {
                door.openAmount =
                    Math.min(
                        door.targetOpen,
                        door.openAmount +
                            step
                    );
            } else if (
                door.openAmount >
                door.targetOpen
            ) {
                door.openAmount =
                    Math.max(
                        door.targetOpen,
                        door.openAmount -
                            step
                    );
            }

            door.angle =
                door.maxAngle *
                door.openAmount *
                (
                    door.hinge ===
                        "left"
                        ? 1
                        : -1
                );

            door.open =
                door.openAmount >=
                0.92;
        }
    }


    function handleDoorInteraction() {
        const player =
            state.player;

        const world =
            state.world;

        if (
            !player ||
            !world ||
            state.dialogue ||
            state.activePanel ||
            state.battle ||
            state.cutscene
        ) {
            return false;
        }

        let nearest =
            null;

        let nearestDistance =
            Infinity;

        for (
            const door of
            safeArray(
                world.doors
            )
        ) {
            const x =
                finiteNumber(
                    door.centerX,
                    door.x +
                        door.w /
                            2
                );

            const y =
                finiteNumber(
                    door.centerY,
                    door.y +
                        door.h /
                            2
                );

            const dist =
                distance(
                    player.x,
                    player.y,
                    x,
                    y
                );

            if (
                dist <=
                    GAME_CONFIG
                        .doorEnterDistance +
                        30 &&
                dist <
                    nearestDistance
            ) {
                nearest =
                    door;

                nearestDistance =
                    dist;
            }
        }

        if (
            state.houseMode
        ) {
            if (
                !nearest
            ) {
                return false;
            }

            nearest.targetOpen =
                1;

            if (
                nearest.openAmount <
                0.68
            ) {
                return true;
            }

            return exitHouse();
        }

        if (
            !nearest ||
            !nearest.houseId ||
            nearest.locked
        ) {
            return false;
        }

        nearest.targetOpen =
            1;

        if (
            nearest.openAmount <
            0.68
        ) {
            return true;
        }

        return enterHouse(
            nearest.houseId
        );
    }


    /* ============================================================
       CAMA / DESCANSO
       ============================================================ */

    function beginBedRest() {
        const player =
            state.player;

        if (
            !player ||
            !V.canRestAtBed(
                player
            ) ||
            player.resting
                ?.active
        ) {
            return false;
        }

        player.resting = {
            active:
                true,

            timer:
                0,

            duration:
                GAME_CONFIG
                    .restDurationSeconds,

            applied:
                false
        };

        state.transition = {
            type:
                "rest",

            timer:
                0,

            duration:
                GAME_CONFIG
                    .restDurationSeconds,

            title:
                "DESCANSANDO"
        };

        return true;
    }


    function updateResting(
        dt
    ) {
        const player =
            state.player;

        const resting =
            player
                ?.resting;

        if (
            !resting
                ?.active
        ) {
            return;
        }

        resting.timer +=
            dt;

        if (
            state.transition
                ?.type ===
            "rest"
        ) {
            state.transition.timer =
                resting.timer;
        }

        if (
            resting.timer <
            resting.duration
        ) {
            return;
        }

        if (
            !resting.applied
        ) {
            resting.applied =
                true;

            applyBedRest(
                player
            );

            pushNotification(
                "DESCANSO CONCLUÍDO",
                "Energia restaurada e Exaustão reduzida.",
                "success",
                2.2
            );
        }

        resting.active =
            false;

        if (
            state.transition
                ?.type ===
            "rest"
        ) {
            state.transition =
                null;
        }
    }


    /* ============================================================
       INTERAÇÕES
       ============================================================ */

    function updateInteractionTargets() {
        const player =
            state.player;

        const world =
            state.world;

        gameplayRuntime.interactionTarget =
            null;

        gameplayRuntime.interactionPrompt =
            null;

        gameplayRuntime.nearbyDoor =
            null;

        gameplayRuntime.nearbyExit =
            null;

        gameplayRuntime.nearbyResource =
            null;

        gameplayRuntime.nearbyNPC =
            null;

        if (
            !player ||
            !world ||
            player.dead
        ) {
            return;
        }

        const boss =
            getNearbyUnconfirmedBoss();

        if (
            boss
        ) {
            gameplayRuntime.interactionTarget = {
                type:
                    "boss",
                entity:
                    boss
            };

            gameplayRuntime.interactionPrompt = {
                key:
                    "E",
                text:
                    `ENFRENTAR ${boss.name}`
            };

            return;
        }

        for (
            const interactable of
            safeArray(
                world.interactables
            )
        ) {
            if (
                interactable.collected
            ) {
                continue;
            }

            if (
                distance(
                    player.x,
                    player.y,
                    interactable.x,
                    interactable.y
                ) >
                finiteNumber(
                    interactable.radius,
                    GAME_CONFIG
                        .interactionDistance
                )
            ) {
                continue;
            }

            if (
                interactable.type ===
                "bedRest"
            ) {
                gameplayRuntime.interactionTarget = {
                    type:
                        "bed",
                    entity:
                        interactable
                };

                gameplayRuntime.interactionPrompt = {
                    key:
                        "E",
                    text:
                        "DESCANSAR"
                };

                return;
            }

            if (
                interactable.type ===
                "monarchAltar"
            ) {
                gameplayRuntime.interactionTarget = {
                    type:
                        "monarchAltar",
                    entity:
                        interactable
                };

                gameplayRuntime.interactionPrompt = {
                    key:
                        "E",
                    text:
                        "TOCAR O ALTAR"
                };

                return;
            }

            if (
                interactable.type ===
                "darkKey"
            ) {
                gameplayRuntime.interactionTarget = {
                    type:
                        "darkKey",
                    entity:
                        interactable
                };

                gameplayRuntime.interactionPrompt = {
                    key:
                        "SEGURE E",

                    text:
                        `CHAVE OBSCURA • ${getItemCount(
                            "essenciaSombria"
                        )}/${VOID_MISSION_CONFIG.shadowEssenceRequired}`
                };

                return;
            }

            if (
                interactable.type ===
                "voidFragment"
            ) {
                gameplayRuntime.interactionTarget = {
                    type:
                        "voidFragment",
                    entity:
                        interactable
                };

                gameplayRuntime.interactionPrompt = {
                    key:
                        "E",
                    text:
                        "TOCAR O FRAGMENTO DO VAZIO"
                };

                return;
            }
        }

        let nearestNPC =
            null;

        let npcDistance =
            Infinity;

        for (
            const npc of
            safeArray(
                world.npcs
            )
        ) {
            const dist =
                distance(
                    player.x,
                    player.y,
                    npc.x,
                    npc.y
                );

            if (
                dist <=
                    GAME_CONFIG
                        .npcInteractionDistance &&
                dist <
                    npcDistance
            ) {
                nearestNPC =
                    npc;

                npcDistance =
                    dist;
            }
        }

        if (
            nearestNPC
        ) {
            gameplayRuntime.interactionTarget = {
                type:
                    "npc",
                entity:
                    nearestNPC
            };

            gameplayRuntime.interactionPrompt = {
                key:
                    "E",
                text:
                    `CONVERSAR COM ${nearestNPC.name}`
            };

            return;
        }

        for (
            const secretDoor of
            safeArray(
                world.secretDoors
            )
        ) {
            const x =
                secretDoor.x +
                secretDoor.w /
                    2;

            const y =
                secretDoor.y +
                secretDoor.h /
                    2;

            if (
                distance(
                    player.x,
                    player.y,
                    x,
                    y
                ) <=
                120
            ) {
                gameplayRuntime.interactionTarget = {
                    type:
                        "secretDoor",
                    entity:
                        secretDoor
                };

                gameplayRuntime.interactionPrompt = {
                    key:
                        "E",

                    text:
                        secretDoor.opened
                            ? "ENTRAR NA PASSAGEM"
                            : "EXAMINAR O SELO"
                };

                return;
            }
        }

        for (
            const resource of
            safeArray(
                world.resources
            )
        ) {
            if (
                resource.harvested
            ) {
                continue;
            }

            if (
                distance(
                    player.x,
                    player.y,
                    resource.x,
                    resource.y
                ) <=
                95
            ) {
                gameplayRuntime.interactionTarget = {
                    type:
                        "resource",
                    entity:
                        resource
                };

                gameplayRuntime.interactionPrompt = {
                    key:
                        "SEGURE E",

                    text:
                        `COLETAR ${ITEMS[resource.itemId]?.name?.toUpperCase() || "RECURSO"}`
                };

                return;
            }
        }

        for (
            const tree of
            safeArray(
                world.trees
            )
        ) {
            if (
                tree.harvested ||
                tree.harvestable ===
                    false
            ) {
                continue;
            }

            if (
                distance(
                    player.x,
                    player.y,
                    tree.x,
                    tree.y +
                        16
                ) <=
                76
            ) {
                gameplayRuntime.interactionTarget = {
                    type:
                        "tree",
                    entity:
                        tree
                };

                gameplayRuntime.interactionPrompt = {
                    key:
                        "SEGURE E",
                    text:
                        "COLETAR MADEIRA"
                };

                return;
            }
        }

        for (
            const exit of
            safeArray(
                world.exits
            )
        ) {
            if (
                circleRectCollision(
                    player.x,
                    player.y,
                    player.radius,
                    {
                        x:
                            exit.x -
                            20,

                        y:
                            exit.y -
                            20,

                        w:
                            exit.w +
                            40,

                        h:
                            exit.h +
                            40
                    }
                )
            ) {
                gameplayRuntime.interactionTarget = {
                    type:
                        "exit",
                    entity:
                        exit
                };

                gameplayRuntime.interactionPrompt = {
                    key:
                        exit.interactionKey ||
                        "E",

                    text:
                        exit.unlocked
                            ? exit.label
                            : exit.lockedMessage
                };

                return;
            }
        }

        let doorDistance =
            Infinity;

        for (
            const door of
            safeArray(
                world.doors
            )
        ) {
            const x =
                finiteNumber(
                    door.centerX,
                    door.x +
                        door.w /
                            2
                );

            const y =
                finiteNumber(
                    door.centerY,
                    door.y +
                        door.h /
                            2
                );

            const dist =
                distance(
                    player.x,
                    player.y,
                    x,
                    y
                );

            if (
                dist <=
                    GAME_CONFIG
                        .doorEnterDistance +
                        35 &&
                dist <
                    doorDistance
            ) {
                doorDistance =
                    dist;

                gameplayRuntime.nearbyDoor =
                    door;
            }
        }

        if (
            gameplayRuntime
                .nearbyDoor
        ) {
            gameplayRuntime.interactionTarget = {
                type:
                    "door",

                entity:
                    gameplayRuntime
                        .nearbyDoor
            };

            gameplayRuntime.interactionPrompt = {
                key:
                    "Z",

                text:
                    state.houseMode
                        ? "SAIR"
                        : "ENTRAR"
            };
        }
    }


    function getInteractionPrompt() {
        return gameplayRuntime
            .interactionPrompt;
    }


    /* ============================================================
       VIAGEM / PORTÃO NORTE
       ============================================================ */

    function performAreaTravel(
        destination,
        spawnId =
            "default",
        title =
            ""
    ) {
        if (
            !destination
        ) {
            return false;
        }

        if (
            typeof V
                .beginAreaTransition ===
            "function"
        ) {
            return V.beginAreaTransition(
                destination,
                spawnId,
                title
            );
        }

        const result =
            loadWorld(
                destination,
                spawnId
            );

        if (
            result
        ) {
            repairWorldProgressionState(
                state.world
            );

            saveGame({
                silent:
                    true,
                safe:
                    true
            });
        }

        return result;
    }


    function requestNorthGateUnlock() {
        const player =
            state.player;

        const status =
            getNorthGateStatus(
                player
            );

        if (
            !player
        ) {
            return false;
        }

        if (
            status.state ===
            "already_open"
        ) {
            return true;
        }

        if (
            status.state ===
            "needs_dash"
        ) {
            player
                .gateDialogueIndex
                .north =
                integer(
                    player
                        .gateDialogueIndex
                        .north,
                    0
                ) +
                1;

            startDialogue(
                [
                    status.message
                ],
                {
                    speaker:
                        "PORTÃO NORTE"
                }
            );

            return false;
        }

        if (
            status.state ===
            "missing_materials"
        ) {
            pushNotification(
                "O SELO EXIGE UMA OFERENDA",

                `Rubi ${getItemCount("rubi")}/${NORTH_GATE_OFFERING.rubi} • Diamante ${getItemCount("diamante")}/${NORTH_GATE_OFFERING.diamante}`,

                "warning",

                3
            );

            return false;
        }

        state.battle = {
            type:
                "northGateConfirmation",

            title:
                "PORTÃO NORTE",

            subtitle:
                `Oferecer ${NORTH_GATE_OFFERING.rubi} Rubis e ${NORTH_GATE_OFFERING.diamante} Diamantes?`,

            acceptLabel:
                "OFERECER",

            retreatLabel:
                "RECUAR"
        };

        return true;
    }


    function acceptNorthGateUnlock() {
        if (
            state.battle
                ?.type !==
            "northGateConfirmation"
        ) {
            return false;
        }

        state.battle =
            null;

        if (
            !unlockNorthGate(
                state.player
            )
        ) {
            return false;
        }

        pushNotification(
            "CAMINHO 2 DESBLOQUEADO",
            "O Portão Norte reconheceu o Passo do Vento.",
            "special",
            3
        );

        return true;
    }


