            projectileHitsSolid,
            getAllCombatEnemies,
            applyProjectileSecondaryEffect,
            updateProjectiles,
            pointToSegmentDistance,
            playerInsideHazard,
            updateHazards,

            getPlayerAimVector,
            angleBetween,
            performMeleeArcAttack,
            damageEnemiesInRadius,
