    function drawMushroom(
        ctx,
        mushroom
    ) {
        const screen =
            worldToScreen(
                mushroom.x,
                mushroom.y
            );

        const scale =
            mushroom.scale ||
            1;

        const sway =
            Math.sin(
                renderRuntime
                    .ambientTime *
                    1.15 +
                mushroom.x *
                    0.013
            ) *
            0.035;

        ctx.save();

        ctx.translate(
            screen.x,
            screen.y
        );

        ctx.rotate(
            sway
        );

        ctx.scale(
            scale,
            scale
        );

        ctx.fillStyle =
            "rgba(0,0,0,0.2)";

        ctx.beginPath();

        ctx.ellipse(
            4,
            9,
            17,
            6,
            0,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        ctx.fillStyle =
            "#d2c1a1";

        roundRectPath(
            ctx,
            -5,
            -7,
            10,
            18,
            5
        );

        ctx.fill();

        ctx.fillStyle =
            mushroom.color ||
            "#527f88";

        ctx.beginPath();

        ctx.ellipse(
            0,
            -10,
            18,
            10,
            0,
            Math.PI,
            Math.PI *
                2
        );

        ctx.closePath();

        ctx.fill();

        ctx.fillStyle =
            "rgba(225,241,234,0.5)";

        ctx.beginPath();

        ctx.arc(
            -6,
            -14,
            2.5,
            0,
            Math.PI *
                2
        );

        ctx.arc(
            5,
            -12,
            2,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        ctx.restore();
    }


    /* ============================================================
       PEDRAS / RECURSOS
       ============================================================ */

    function drawRocks(
        ctx
    ) {
        const world =
            state.world;

        if (!world) {
            return;
        }

        for (
            const rock of
            safeArray(
                world.rocks
            )
        ) {
            if (
                !isPointVisible(
                    rock.x,
                    rock.y,
                    80
                )
            ) {
                continue;
            }

            const screen =
                worldToScreen(
                    rock.x,
                    rock.y
                );

            const radius =
                rock.radius ||
                26;

            ctx.save();

            ctx.fillStyle =
                "rgba(0,0,0,0.23)";

            ctx.beginPath();

            ctx.ellipse(
                screen.x +
                    4,
                screen.y +
                    8,
                radius,
                radius *
                    0.42,
                0,
                0,
                Math.PI *
                    2
            );

            ctx.fill();

            ctx.fillStyle =
                rock.color ||
                "#676b68";

            ctx.beginPath();

            ctx.moveTo(
                screen.x -
                    radius,
                screen.y +
                    5
            );

            ctx.lineTo(
                screen.x -
                    radius *
                        0.55,
                screen.y -
                    radius *
                        0.72
            );

            ctx.lineTo(
                screen.x +
                    radius *
                        0.45,
                screen.y -
                    radius
            );

            ctx.lineTo(
                screen.x +
                    radius,
                screen.y +
                    radius *
                        0.18
            );

            ctx.lineTo(
                screen.x +
                    radius *
                        0.45,
                screen.y +
                    radius *
                        0.62
            );

            ctx.lineTo(
                screen.x -
                    radius *
                        0.7,
                screen.y +
                    radius *
                        0.55
            );

            ctx.closePath();

            ctx.fill();

            ctx.restore();
        }
    }


    function drawResources(
        ctx
    ) {
        const world =
            state.world;

        if (!world) {
            return;
        }

        for (
            const resource of
            safeArray(
                world.resources
            )
        ) {
            if (
                resource.harvested ||
                !isPointVisible(
                    resource.x,
                    resource.y,
                    80
                )
            ) {
                continue;
            }

            const screen =
                worldToScreen(
                    resource.x,
                    resource.y
                );

            const item =
                ITEMS[
                    resource.itemId
                ];

            const pulse =
                0.85 +
                Math.sin(
                    renderRuntime
                        .ambientTime *
                        2.1 +
                    resource.x *
                        0.015
                ) *
                    0.08;

            ctx.save();

            ctx.translate(
                screen.x,
                screen.y
            );

            ctx.scale(
                pulse,
                pulse
            );

            ctx.shadowBlur =
                12;

            ctx.shadowColor =
                resource.glow ||
                "rgba(255,255,255,0.2)";

          if (
    resource.itemId ===
    "madeira"
) {
    ctx.shadowBlur =
        0;

    ctx.font =
        "30px sans-serif";

    ctx.textAlign =
        "center";

    ctx.textBaseline =
        "middle";

    ctx.fillStyle =
        "#ffffff";


    ctx.fillText(
        "🪵",
        0,
        0
    );
}

else if (
    resource.type ===
        "ore" ||
    resource.itemId ===
        "ferro" ||
    resource.itemId ===
        "ouro" ||
    resource.itemId ===
        "diamante" ||
    resource.itemId ===
        "rubi" ||
    resource.itemId ===
        "carvao"
) {
    drawOreNode(
        ctx,
        resource
    );
}

else {
    ctx.font =
        "26px sans-serif";

    ctx.textAlign =
        "center";

    ctx.textBaseline =
        "middle";

    ctx.fillText(
        item?.icon ||
            "◆",
        0,
        0
    );
}

            ctx.shadowBlur =
                0;

            if (
                item
            ) {
                ctx.fillStyle =
                    "rgba(235,230,215,0.72)";

                ctx.font =
                    "10px serif";

                ctx.textAlign =
                    "center";

                ctx.fillText(
                    item.name,
                    0,
                    36
                );
            }

            ctx.restore();
        }
    }


    function drawOreNode(
        ctx,
        resource
    ) {
        const colors = {
            carvao:
                "#343438",

            ferro:
                "#959b9c",

            ouro:
                "#c5a34c",

            diamante:
                "#8bc1cc",

            rubi:
                "#b14d63"
        };

        const color =
            colors[
                resource.itemId
            ] ||
            "#8b8176";

        ctx.fillStyle =
            "#494747";

        ctx.beginPath();

        ctx.moveTo(
            -23,
            10
        );

        ctx.lineTo(
            -15,
            -15
        );

        ctx.lineTo(
            4,
            -25
        );

        ctx.lineTo(
            23,
            -10
        );

        ctx.lineTo(
            19,
            14
        );

        ctx.lineTo(
            -7,
            21
        );

        ctx.closePath();

        ctx.fill();

        ctx.fillStyle =
            color;

        for (
            const point of
            [
                [-10, -8],
                [8, -13],
                [12, 5],
                [-5, 8]
            ]
        ) {
            ctx.beginPath();

            ctx.arc(
                point[0],
                point[1],
                4,
                0,
                Math.PI *
                    2
            );

            ctx.fill();
        }
    }


    /* ============================================================
       ÁRVORES

       TRONCO = COLISÃO
       COPA = SEM COLISÃO

       A árvore entra no MESMO Y-SORT
       de player/NPC/inimigo/boss.
       ============================================================ */

    function drawTree(
        ctx,
        tree
    ) {
        if (
            tree.harvested ||
            !isPointVisible(
                tree.x,
                tree.y,
                150
            )
        ) {
            return;
        }

        const screen =
            worldToScreen(
                tree.x,
                tree.y
            );

        const style =
            tree.style ||
            {};

        const scale =
            tree.scale ||
            1;

        const sway =
            Math.sin(
                renderRuntime
                    .ambientTime *
                    1.1 +
                tree.x *
                    0.009 +
                tree.y *
                    0.007
            ) *
            0.035;

        ctx.save();

        ctx.translate(
            screen.x,
            screen.y
        );

        ctx.scale(
            scale,
            scale
        );

        /*
            Sombra no solo.
        */
        ctx.fillStyle =
            "rgba(0,0,0,0.24)";

        ctx.beginPath();

        ctx.ellipse(
            12,
            15,
            45,
            17,
            0,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Tronco.
        */
        const trunkGradient =
            ctx.createLinearGradient(
                -12,
                0,
                15,
                0
            );

        trunkGradient.addColorStop(
            0,
            style.trunkDark ||
                "#34271f"
        );

        trunkGradient.addColorStop(
            0.5,
            style.trunk ||
                "#604833"
        );

        trunkGradient.addColorStop(
            1,
            style.trunkLight ||
                "#75583c"
        );

        ctx.fillStyle =
            trunkGradient;

        roundRectPath(
            ctx,
            -12,
            -58,
            24,
            76,
            8
        );

        ctx.fill();

        /*
            Galhos.
        */
        ctx.strokeStyle =
            style.trunk ||
            "#604833";

        ctx.lineWidth =
            10;

        ctx.lineCap =
            "round";

        ctx.beginPath();

        ctx.moveTo(
            -3,
            -42
        );

        ctx.lineTo(
            -26,
            -72
        );

        ctx.moveTo(
            4,
            -48
        );

        ctx.lineTo(
            27,
            -78
        );

        ctx.stroke();

        /*
            Copa balançando.
        */
        ctx.translate(
            sway *
                55,
            0
        );

        ctx.rotate(
            sway
        );

        const canopy =
            style.canopy ||
            "#435f42";

        const canopyDark =
            style.canopyDark ||
            "#2f4833";

        ctx.fillStyle =
            canopyDark;

        ctx.beginPath();

        ctx.arc(
            -22,
            -91,
            38,
            0,
            Math.PI *
                2
        );

        ctx.arc(
            22,
            -95,
            43,
            0,
            Math.PI *
                2
        );

        ctx.arc(
            0,
            -120,
            47,
            0,
            Math.PI *
                2
        );

        ctx.arc(
            0,
            -80,
            45,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        ctx.fillStyle =
            canopy;

        ctx.globalAlpha =
            0.92;

        ctx.beginPath();

        ctx.arc(
            -17,
            -101,
            31,
            0,
            Math.PI *
                2
        );

        ctx.arc(
            18,
            -105,
            34,
            0,
            Math.PI *
                2
        );

        ctx.arc(
            0,
            -129,
            35,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        ctx.globalAlpha =
            1;

        /*
            Pequenos brilhos/reflexos.
        */
        ctx.fillStyle =
            "rgba(205,225,187,0.13)";

        ctx.beginPath();

        ctx.arc(
            -15,
            -124,
            12,
            0,
            Math.PI *
                2
        );

        ctx.arc(
            17,
            -105,
            9,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        ctx.restore();

        renderRuntime
            .frameStats
            .drawnTrees +=
            1;
    }


    /* ============================================================
       NPC
       ============================================================ */

    function drawNPC(
        ctx,
        npc
    ) {
        if (
            !npc ||
            !isPointVisible(
                npc.x,
                npc.y,
                100
            )
        ) {
            return;
        }

        const screen =
            worldToScreen(
                npc.x,
                npc.y
            );

        const bob =
            Math.sin(
                renderRuntime
                    .ambientTime *
                    2 +
                npc.x *
                    0.01
            ) *
            1.5;

        ctx.save();

        ctx.translate(
            screen.x,
            screen.y +
                bob
        );

        /*
            Sombra.
        */
        ctx.fillStyle =
            "rgba(0,0,0,0.24)";

        ctx.beginPath();

        ctx.ellipse(
            0,
            17,
            16,
            6,
            0,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Corpo.
        */
        ctx.fillStyle =
            npc.color ||
            "#7a6857";

        roundRectPath(
            ctx,
            -11,
            -9,
            22,
            31,
            8
        );

        ctx.fill();

        /*
            Cabeça.
        */
        ctx.fillStyle =
            npc.skinColor ||
            "#c3a98e";

        ctx.beginPath();

        ctx.arc(
            0,
            -18,
            11,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Cabelo/capuz.
        */
        ctx.fillStyle =
            npc.hairColor ||
            "#3c342e";

        ctx.beginPath();

        ctx.arc(
            0,
            -22,
            11,
            Math.PI,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Nome.
        */
        ctx.font =
            "600 11px serif";

        ctx.textAlign =
            "center";

        ctx.fillStyle =
            "rgba(237,229,211,0.88)";

        ctx.fillText(
            npc.name ||
                "",
            0,
            -39
        );

        ctx.restore();

        renderRuntime
            .frameStats
            .drawnEntities +=
            1;
    }


    /* ============================================================
       PLAYER — BASE
       ============================================================ */

    function drawPlayer(
        ctx
    ) {
        const player =
            state.player;

        if (
            !player ||
            player.dead
        ) {
            return;
        }

        const screen =
            worldToScreen(
                player.x,
                player.y
            );

        const character =
            currentCharacter();

        const profile =
            character
                .visualProfile ||
            {};

        const walk =
            Math.sin(
                finiteNumber(
                    player.visual
                        ?.walkTime,
                    0
                ) *
                    12
            );

        ctx.save();

        ctx.translate(
            screen.x,
            screen.y
        );

        /*
            Sombra.
        */
        ctx.fillStyle =
            "rgba(0,0,0,0.27)";

        ctx.beginPath();

        ctx.ellipse(
            0,
            17,
            18,
            7,
            0,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        switch (
            character.id
        ) {
            case "theron":
                drawTheron(
                    ctx,
                    player,
                    profile,
                    walk
                );
                break;

            case "grumgar":
                drawGrumgar(
                    ctx,
                    player,
                    profile,
                    walk
                );
                break;

            case "lirael":
                drawLirael(
                    ctx,
                    player,
                    profile,
                    walk
                );
                break;

            case "zephyr":
                drawZephyr(
                    ctx,
                    player,
                    profile,
                    walk
                );
                break;

            case "kaelion":
            default:
                drawKaelion(
                    ctx,
                    player,
                    profile,
                    walk
                );
                break;
        }

        drawPlayerArmorOverlay(
            ctx,
            player
        );

        ctx.restore();

        renderRuntime
            .frameStats
            .drawnEntities +=
            1;
    }


    /* ============================================================
       KAELION
       ============================================================ */

    function drawKaelion(
        ctx,
        player,
        profile,
        walk
    ) {
        ctx.save();

        ctx.translate(
            0,
            Math.abs(
                walk
            ) *
                -1
        );

        /*
            Robe.
        */
        ctx.fillStyle =
            profile.robeColor ||
            "#6d3725";

        ctx.beginPath();

        ctx.moveTo(
            -12,
            -5
        );

        ctx.lineTo(
            -18,
            20
        );

        ctx.lineTo(
            17,
            20
        );

        ctx.lineTo(
            11,
            -5
        );

        ctx.closePath();

        ctx.fill();

        /*
            Cinto.
        */
        ctx.fillStyle =
            "#33241d";

        ctx.fillRect(
            -12,
            1,
            24,
            5
        );

        /*
            Cabeça.
        */
        ctx.fillStyle =
            "#c6a287";

        ctx.beginPath();

        ctx.arc(
            0,
            -17,
            11,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Capuz/cabelo.
        */
        ctx.fillStyle =
            "#39291f";

        ctx.beginPath();

        ctx.arc(
            0,
            -21,
            12,
            Math.PI,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Cajado.
        */
        ctx.strokeStyle =
            "#67462e";

        ctx.lineWidth =
            4;

        ctx.beginPath();

        ctx.moveTo(
            14,
            -4
        );

        ctx.lineTo(
            20,
            -36
        );

        ctx.stroke();

        ctx.fillStyle =
            "#d57a42";

        ctx.shadowColor =
            "#d57a42";

        ctx.shadowBlur =
            12;

        ctx.beginPath();

        ctx.arc(
            21,
            -40,
            5,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        ctx.shadowBlur =
            0;

        ctx.restore();
    }


    /* ============================================================
       THERON
       ============================================================ */

    function drawTheron(
        ctx,
        player,
        profile,
        walk
    ) {
        ctx.save();

        /*
            Pernas.
        */
        ctx.strokeStyle =
            "#6f7478";

        ctx.lineWidth =
            7;

        ctx.beginPath();

        ctx.moveTo(
            -6,
            9
        );

        ctx.lineTo(
            -7 +
                walk *
                    2,
            22
        );

        ctx.moveTo(
            6,
            9
        );

        ctx.lineTo(
            7 -
                walk *
                    2,
            22
        );

        ctx.stroke();

        /*
            Armadura.
        */
        ctx.fillStyle =
            profile.armorColor ||
            "#a9afb2";

        roundRectPath(
            ctx,
            -14,
            -12,
            28,
            31,
            7
        );

        ctx.fill();

        ctx.strokeStyle =
            "#4c545a";

        ctx.lineWidth =
            3;

        ctx.stroke();

        /*
            Capacete.
        */
        ctx.fillStyle =
            "#8e969b";

        ctx.beginPath();

        ctx.arc(
            0,
            -20,
            12,
            Math.PI,
            Math.PI *
                2
        );

        ctx.lineTo(
            11,
            -12
        );

        ctx.lineTo(
            -11,
            -12
        );

        ctx.closePath();

        ctx.fill();

        /*
            Espada.
        */
        ctx.strokeStyle =
            "#d4d7d5";

        ctx.lineWidth =
            4;

        ctx.beginPath();

        ctx.moveTo(
            14,
            3
        );

        ctx.lineTo(
            28,
            -23
        );

        ctx.stroke();

        /*
            Escudo.
        */
        ctx.fillStyle =
            "#66727a";

        ctx.beginPath();

        ctx.moveTo(
            -18,
            -5
        );

        ctx.lineTo(
            -29,
            0
        );

        ctx.lineTo(
            -26,
            15
        );

        ctx.lineTo(
            -18,
            22
        );

        ctx.lineTo(
            -11,
            15
        );

        ctx.lineTo(
            -9,
            0
        );

        ctx.closePath();

        ctx.fill();

        ctx.restore();
    }


    /* ============================================================
       GRUMGAR
       ============================================================ */

    function drawGrumgar(
        ctx,
        player,
        profile,
        walk
    ) {
        ctx.save();

        ctx.scale(
            1.15,
            1.15
        );

        /*
            Corpo grande.
        */
        ctx.fillStyle =
            profile.skinColor ||
            "#6b7d4a";

        roundRectPath(
            ctx,
            -17,
            -12,
            34,
            34,
            11
        );

        ctx.fill();

        /*
            Cabeça.
        */
        ctx.beginPath();

        ctx.arc(
            0,
            -22,
            14,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Ombros.
        */
        ctx.fillStyle =
            "#463e30";

        ctx.beginPath();

        ctx.arc(
            -17,
            -5,
            9,
            0,
            Math.PI *
                2
        );

        ctx.arc(
            17,
            -5,
            9,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Presas.
        */
        ctx.fillStyle =
            "#e0d4b4";

        ctx.beginPath();

        ctx.moveTo(
            -7,
            -16
        );

        ctx.lineTo(
            -3,
            -8
        );

        ctx.lineTo(
            -1,
            -17
        );

        ctx.closePath();

        ctx.moveTo(
            7,
            -16
        );

        ctx.lineTo(
            3,
            -8
        );

        ctx.lineTo(
            1,
            -17
        );

        ctx.closePath();

        ctx.fill();

        ctx.restore();
    }


    /* ============================================================
       LIRAEL
       ============================================================ */

    function drawLirael(
        ctx,
        player,
        profile,
        walk
    ) {
        ctx.save();

        const wing =
            0.8 +
            Math.sin(
                renderRuntime
                    .ambientTime *
                    8
            ) *
                0.12;

        /*
            Asas.
        */
        ctx.fillStyle =
            "rgba(235,190,230,0.48)";

        ctx.beginPath();

        ctx.ellipse(
            -16,
            -7,
            9 *
                wing,
            19,
            -0.45,
            0,
            Math.PI *
                2
        );

        ctx.ellipse(
            16,
            -7,
            9 *
                wing,
            19,
            0.45,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Corpo.
        */
        ctx.fillStyle =
            profile.dressColor ||
            "#ba779e";

        ctx.beginPath();

        ctx.moveTo(
            -9,
            -4
        );

        ctx.lineTo(
            -14,
            20
        );

        ctx.lineTo(
            14,
            20
        );

        ctx.lineTo(
            9,
            -4
        );

        ctx.closePath();

        ctx.fill();

        /*
            Cabeça.
        */
        ctx.fillStyle =
            "#d9baa4";

        ctx.beginPath();

        ctx.arc(
            0,
            -17,
            10,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Cabelo.
        */
        ctx.fillStyle =
            "#ead1df";

        ctx.beginPath();

        ctx.arc(
            0,
            -21,
            11,
            Math.PI,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Brilho.
        */
        ctx.shadowColor =
            "#efb4df";

        ctx.shadowBlur =
            16;

        ctx.strokeStyle =
            "rgba(239,180,223,0.5)";

        ctx.lineWidth =
            2;

        ctx.beginPath();

        ctx.arc(
            0,
            0,
            24,
            0,
            Math.PI *
                2
        );

        ctx.stroke();

        ctx.shadowBlur =
            0;

        ctx.restore();
    }


    /* ============================================================
       ZEPHYR
       ============================================================ */

    function drawZephyr(
        ctx,
        player,
        profile,
        walk
    ) {
        ctx.save();

        /*
            Rastro instável.
        */
        ctx.globalAlpha =
            0.2;

        ctx.fillStyle =
            "#74548c";

        for (
            let index = 1;
            index <= 3;
            index += 1
        ) {
            ctx.beginPath();

            ctx.arc(
                -index *
                    7,
                index *
                    2,
                11 -
                    index *
                        2,
                0,
                Math.PI *
                    2
            );

            ctx.fill();
        }

        ctx.globalAlpha =
            1;

        /*
            Corpo.
        */
        ctx.fillStyle =
            profile.bodyColor ||
            "#665078";

        roundRectPath(
            ctx,
            -12,
            -10,
            24,
            31,
            9
        );

        ctx.fill();

        /*
            Manto assimétrico.
        */
        ctx.fillStyle =
            "#3e334b";

        ctx.beginPath();

        ctx.moveTo(
            -12,
            -3
        );

        ctx.lineTo(
            -23,
            19
        );

        ctx.lineTo(
            4,
            13
        );

        ctx.closePath();

        ctx.fill();

        /*
            Cabeça.
        */
        ctx.fillStyle =
            "#b79d91";

        ctx.beginPath();

        ctx.arc(
            0,
            -19,
            10,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Olho de fenda.
        */
        ctx.fillStyle =
            "#b592d2";

        ctx.shadowColor =
            "#9a71ba";

        ctx.shadowBlur =
            10;

        ctx.fillRect(
            2,
            -21,
            5,
            2
        );

        ctx.shadowBlur =
            0;

        ctx.restore();
    }


    /* ============================================================
       ARMADURA DO PLAYER
       ============================================================ */

    function drawPlayerArmorOverlay(
        ctx,
        player
    ) {
        const armorId =
            player.equipment
                ?.armor;

        const armor =
            ARMOR_DATA[
                armorId
            ];

        if (!armor) {
            return;
        }

        const armorColors = {
            armaduraFolha:
                "#59734b",

            armaduraAlgodao:
                "#d5d1c6",

            armaduraMadeira:
                "#78553c",

            armaduraCouro:
                "#6e4935",

            armaduraFerro:
                "#8e9699",

            armaduraOuro:
                "#b89a4b",

            armaduraDiamante:
                "#78aab4",

            armaduraRubi:
                "#a94d5c"
        };

        ctx.save();

        ctx.strokeStyle =
            armorColors[
                armorId
            ] ||
            "#aaa";

        ctx.lineWidth =
            3;

        ctx.globalAlpha =
            0.75;

        ctx.beginPath();

        ctx.arc(
            0,
            2,
            17,
            0.3,
            Math.PI -
                0.3
        );

        ctx.stroke();

        ctx.restore();
    }


    /* ============================================================
       INIMIGOS
       ============================================================ */

    function drawEnemy(
        ctx,
        enemy
    ) {
        if (
            !enemy ||
            (
                enemy.dead &&
                enemy.deathTimer >
                    0.7
            ) ||
            !isPointVisible(
                enemy.x,
                enemy.y,
                120
            )
        ) {
            return;
        }

        const screen =
            worldToScreen(
                enemy.x,
                enemy.y
            );

        let alpha =
            1;

        if (
            enemy.dead
        ) {
            alpha =
                clamp(
                    1 -
                    finiteNumber(
                        enemy.deathTimer,
                        0
                    ) /
                        0.75,
                    0,
                    1
                );
        }

        ctx.save();

        ctx.globalAlpha =
            alpha;

        ctx.translate(
            screen.x,
            screen.y
        );

        drawEnemyShadow(
            ctx,
            enemy
        );

        switch (
            enemy.speciesId
        ) {
            case "wolf":
                drawWolfEnemy(
                    ctx,
                    enemy
                );
                break;

            case "boar":
                drawBoarEnemy(
                    ctx,
                    enemy
                );
                break;

            case "bat":
                drawBatEnemy(
                    ctx,
                    enemy
                );
                break;

            case "spider":
            case "voidSpider":
                drawSpiderEnemy(
                    ctx,
                    enemy
                );
                break;

            case "goblin":
            case "voidGoblin":
                drawGoblinEnemy(
                    ctx,
                    enemy
                );
                break;

            default:
                drawGenericEnemy(
                    ctx,
                    enemy
                );
                break;
        }

        ctx.restore();

        drawEnemyTelegraph(
            ctx,
            enemy
        );

        drawEnemyHealthBar(
            ctx,
            enemy
        );

        renderRuntime
            .frameStats
            .drawnEntities +=
            1;
    }


    function drawEnemyShadow(
        ctx,
        enemy
    ) {
        ctx.fillStyle =
            "rgba(0,0,0,0.25)";

        ctx.beginPath();

        ctx.ellipse(
            0,
            enemy.radius *
                0.55,
            enemy.radius *
                0.8,
            enemy.radius *
                0.32,
            0,
            0,
            Math.PI *
                2
        );

        ctx.fill();
    }


    function drawWolfEnemy(
        ctx,
        enemy
    ) {
        const facing =
            state.player
                ? Math.atan2(
                    state.player.y -
                        enemy.y,
                    state.player.x -
                        enemy.x
                )
                : 0;

        ctx.rotate(
            facing
        );

        ctx.fillStyle =
            enemy.color ||
            "#575d58";

        ctx.beginPath();

        ctx.ellipse(
            0,
            0,
            25,
            14,
            0,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        ctx.beginPath();

        ctx.arc(
            21,
            -5,
            12,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Orelhas.
        */
        ctx.beginPath();

        ctx.moveTo(
            16,
            -13
        );

        ctx.lineTo(
            19,
            -25
        );

        ctx.lineTo(
            24,
            -14
        );

        ctx.moveTo(
            25,
            -13
        );

        ctx.lineTo(
            29,
            -24
        );

        ctx.lineTo(
            32,
            -10
        );

        ctx.fill();

        /*
            Olho.
        */
        ctx.fillStyle =
            "#d1a65d";

        ctx.beginPath();

        ctx.arc(
            27,
            -7,
            2.4,
            0,
            Math.PI *
                2
        );

        ctx.fill();
    }


    function drawBoarEnemy(
        ctx,
        enemy
    ) {
        ctx.fillStyle =
            enemy.color ||
            "#674e3e";

        ctx.beginPath();

        ctx.ellipse(
            0,
            0,
            29,
            18,
            0,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        ctx.beginPath();

        ctx.arc(
            22,
            1,
            13,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        ctx.fillStyle =
            "#d7ccb4";

        ctx.beginPath();

        ctx.moveTo(
            29,
            5
        );

        ctx.lineTo(
            39,
            10
        );

        ctx.lineTo(
            31,
            0
        );

        ctx.fill();
    }


    function drawBatEnemy(
        ctx,
        enemy
    ) {
        const flap =
            Math.sin(
                renderRuntime
                    .ambientTime *
                    11 +
                enemy.x *
                    0.01
            );

        ctx.fillStyle =
            enemy.color ||
            "#50475c";

        ctx.beginPath();

        ctx.moveTo(
            -3,
            0
        );

        ctx.quadraticCurveTo(
            -22,
            -15 -
                flap *
                    8,
            -31,
            3
        );

        ctx.quadraticCurveTo(
            -20,
            -2,
            -6,
            9
        );

        ctx.moveTo(
            3,
            0
        );

        ctx.quadraticCurveTo(
            22,
            -15 -
                flap *
                    8,
            31,
            3
        );

        ctx.quadraticCurveTo(
            20,
            -2,
            6,
            9
        );

        ctx.fill();

        ctx.beginPath();

        ctx.ellipse(
            0,
            0,
            9,
            13,
            0,
            0,
            Math.PI *
                2
        );

        ctx.fill();
    }


    function drawSpiderEnemy(
        ctx,
        enemy
    ) {
        ctx.strokeStyle =
            enemy.color ||
            "#4b4449";

        ctx.lineWidth =
            4;

        for (
            let index = -1;
            index <= 1;
            index += 2
        ) {
            for (
                let leg = 0;
                leg < 4;
                leg += 1
            ) {
                const y =
                    -10 +
                    leg *
                        7;

                ctx.beginPath();

                ctx.moveTo(
                    index *
                        7,
                    y
                );

                ctx.lineTo(
                    index *
                        (
                            20 +
                            leg *
                                2
                        ),
                    y -
                        7 +
                        leg *
                            4
                );

                ctx.lineTo(
                    index *
                        (
                            27 +
                            leg *
                                2
                        ),
                    y +
                        2
                );

                ctx.stroke();
            }
        }

        ctx.fillStyle =
            enemy.color ||
            "#4b4449";

        ctx.beginPath();

        ctx.ellipse(
            0,
            4,
            13,
            17,
            0,
            0,
            Math.PI *
                2
        );

        ctx.arc(
            0,
            -10,
            9,
            0,
            Math.PI *
                2
        );

        ctx.fill();
    }


    function drawGoblinEnemy(
        ctx,
        enemy
    ) {
        ctx.fillStyle =
            enemy.color ||
            "#657352";

        roundRectPath(
            ctx,
            -11,
            -6,
            22,
            27,
            7
        );

        ctx.fill();

        ctx.beginPath();

        ctx.arc(
            0,
            -15,
            12,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Orelhas pontudas.
        */
        ctx.beginPath();

        ctx.moveTo(
            -10,
            -18
        );

        ctx.lineTo(
            -23,
            -14
        );

        ctx.lineTo(
            -9,
            -10
        );

        ctx.moveTo(
            10,
            -18
        );

        ctx.lineTo(
            23,
            -14
        );

        ctx.lineTo(
            9,
            -10
        );

        ctx.fill();

        ctx.fillStyle =
            "#c8aa68";

        ctx.fillRect(
            -7,
            -18,
            3,
            2
        );

        ctx.fillRect(
            4,
            -18,
            3,
            2
        );
    }


    function drawGenericEnemy(
        ctx,
        enemy
    ) {
        const radius =
            enemy.radius ||
            18;

        ctx.fillStyle =
            enemy.color ||
            "#71645e";

        ctx.beginPath();

        ctx.arc(
            0,
            0,
            radius,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        ctx.fillStyle =
            "rgba(255,220,180,0.6)";

        ctx.beginPath();

        ctx.arc(
            radius *
                0.3,
            -radius *
                0.2,
            2.5,
            0,
            Math.PI *
                2
        );

        ctx.fill();
    }


    function drawEnemyTelegraph(
        ctx,
        enemy
    ) {
        const telegraph =
            enemy.telegraph;

        if (
            !telegraph ||
            telegraph.timer <=
                0
        ) {
            return;
        }

        const from =
            worldToScreen(
                enemy.x,
                enemy.y
            );

        const target =
            worldToScreen(
                telegraph.x,
                telegraph.y
            );

        ctx.save();

        ctx.strokeStyle =
            "rgba(210,105,85,0.5)";

        ctx.lineWidth =
            telegraph.type ===
            "heavyCharge"
                ? 6
                : 4;

        ctx.setLineDash(
            [
                10,
                8
            ]
        );

        ctx.beginPath();

        ctx.moveTo(
            from.x,
            from.y
        );

        ctx.lineTo(
            target.x,
            target.y
        );

        ctx.stroke();

        ctx.setLineDash(
            []
        );

        ctx.restore();
    }


  function drawEnemyHealthBar(
    ctx,
    enemy
) {
    if (
        !enemy ||
        enemy.dead
    ) {
        return;
    }


    const screen =
        worldToScreen(
            enemy.x,
            enemy.y
        );


    const levels = {

        village:
            1,

        road:
            1,

        forest:
            2,

        grove:
            3,

        mountains:
            4,

        ironRegion:
            5,

        rubyRegion:
            6,

        monarchMaze:
            7,

        gnomeGardens:
            8,

        fairyWoods:
            9,

        celestialFrontier:
            10,

        skyRealm:
            11,

        voidDungeon:
            12

    };


    const level =
        enemy.level ||
        levels[
            state.area
        ] ||
        1;


    const top =
        screen.y -
        enemy.radius -
        37;


    ctx.save();


    /*
        NOME.
    */
    ctx.font =
        "700 11px serif";

    ctx.textAlign =
        "center";

    ctx.fillStyle =
        "rgba(240,233,217,0.96)";


    ctx.fillText(
        enemy.name ||
            "CRIATURA",
        screen.x,
        top
    );


    /*
        NÍVEL.
    */
    ctx.font =
        "700 9px sans-serif";

    ctx.fillStyle =
        "#c9ae70";


    ctx.fillText(
        `NV. ${level}`,
        screen.x,
        top +
            13
    );


    /*
        Vida só aparece
        depois de levar dano.
    */
    if (
        enemy.hp <
        enemy.maxHp
    ) {
        const width =
            44;


        const ratio =
            clamp(
                enemy.hp /
                enemy.maxHp,
                0,
                1
            );


        ctx.fillStyle =
            "rgba(0,0,0,0.65)";


        ctx.fillRect(
            screen.x -
                width /
                    2,
            top +
                19,
            width,
            5
        );


        ctx.fillStyle =
            "#a35353";


        ctx.fillRect(
            screen.x -
                width /
                    2,
            top +
                19,
            width *
                ratio,
            5
        );
    }


    ctx.restore();
}
    function drawBoss(
        ctx,
        boss
    ) {
        if (
            !boss ||
            (
                boss.dead &&
                boss.fade <=
                    0
            ) ||
            !isPointVisible(
                boss.x,
                boss.y,
                220
            )
        ) {
            return;
        }

        const screen =
            worldToScreen(
                boss.x,
                boss.y
            );

        ctx.save();

        ctx.globalAlpha =
            clamp(
                finiteNumber(
                    boss.fade,
                    1
                ),
                0,
                1
            );

        ctx.translate(
            screen.x,
            screen.y
        );

        /*
            Aura.
        */
        const aura =
            boss.definition
                ?.aura ||
            BOSS_REGISTRY[
                boss.id
            ]?.aura ||
            "#806878";

        const pulse =
            1 +
            Math.sin(
                renderRuntime
                    .ambientTime *
                    2.5
            ) *
                0.07;

        ctx.strokeStyle =
            colorWithAlpha(
                aura,
                0.33
            );

        ctx.lineWidth =
            4;

        ctx.beginPath();

        ctx.arc(
            0,
            0,
            boss.radius *
                1.45 *
                pulse,
            0,
            Math.PI *
                2
        );

        ctx.stroke();

        if (
            boss.id ===
            "monarch"
        ) {
            drawMonarchBoss(
                ctx,
                boss
            );
        } else if (
            boss.id ===
            "vaelkor"
        ) {
            drawVaelkorBoss(
                ctx,
                boss
            );
        } else {
            drawPathBoss(
                ctx,
                boss
            );
        }

        ctx.restore();

        renderRuntime
            .frameStats
            .drawnEntities +=
            1;
    }


    function drawPathBoss(
        ctx,
        boss
    ) {
        const aura =
            boss.definition
                ?.aura ||
            "#75808a";

        /*
            Silhueta maior, nada de bolinha genérica.
        */
        ctx.fillStyle =
            "rgba(0,0,0,0.28)";

        ctx.beginPath();

        ctx.ellipse(
            7,
            boss.radius *
                0.55,
            boss.radius *
                0.8,
            boss.radius *
                0.3,
            0,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        ctx.fillStyle =
            colorWithAlpha(
                aura,
                0.76
            );

        ctx.beginPath();

        ctx.moveTo(
            -boss.radius *
                0.5,
            boss.radius *
                0.45
        );

        ctx.lineTo(
            -boss.radius *
                0.36,
            -boss.radius *
                0.45
        );

        ctx.quadraticCurveTo(
            0,
            -boss.radius *
                0.85,
            boss.radius *
                0.36,
            -boss.radius *
                0.45
        );

        ctx.lineTo(
            boss.radius *
                0.5,
            boss.radius *
                0.45
        );

        ctx.closePath();

        ctx.fill();

        ctx.fillStyle =
            "#29252a";

        ctx.beginPath();

        ctx.arc(
            0,
            -boss.radius *
                0.42,
            boss.radius *
                0.38,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Olhos.
        */
        ctx.shadowBlur =
            12;

        ctx.shadowColor =
            aura;

        ctx.fillStyle =
            aura;

        ctx.fillRect(
            -boss.radius *
                0.18,
            -boss.radius *
                0.47,
            6,
            3
        );

        ctx.fillRect(
            boss.radius *
                0.08,
            -boss.radius *
                0.47,
            6,
            3
        );

        ctx.shadowBlur =
            0;

        /*
            Arma específica.
        */
        drawBossWeapon(
            ctx,
            boss
        );
    }


    function drawBossWeapon(
        ctx,
        boss
    ) {
        ctx.strokeStyle =
            "#a6a39d";

        ctx.lineWidth =
            6;

        ctx.lineCap =
            "round";

        switch (
            boss.id
        ) {
            case "road_guardian":
            case "iron_colossus":
                ctx.beginPath();

                ctx.moveTo(
                    25,
                    -10
                );

                ctx.lineTo(
                    50,
                    26
                );

                ctx.stroke();

                break;

            case "forest_warden":
            case "grove_heart":
                ctx.strokeStyle =
                    "#735943";

                ctx.beginPath();

                ctx.moveTo(
                    28,
                    -28
                );

                ctx.lineTo(
                    38,
                    32
                );

                ctx.stroke();

                break;

            case "ruby_chimera":
                ctx.fillStyle =
                    "#a34b5c";

                ctx.beginPath();

                ctx.moveTo(
                    -20,
                    -28
                );

                ctx.lineTo(
                    -31,
                    -50
                );

                ctx.lineTo(
                    -7,
                    -34
                );

                ctx.moveTo(
                    20,
                    -28
                );

                ctx.lineTo(
                    31,
                    -50
                );

                ctx.lineTo(
                    7,
                    -34
                );

                ctx.fill();

                break;
        }
    }


    /* ============================================================
       MONARCA
       ============================================================ */

    function drawMonarchBoss(
        ctx,
        boss
    ) {
        const stagger =
            finiteNumber(
                boss.stagger,
                0
            );

        const threshold =
            boss.definition
                ?.stagger
                ?.threshold ||
            15;

        const crackRatio =
            clamp(
                stagger /
                    threshold,
                0,
                1
            );

        const float =
            Math.sin(
                renderRuntime
                    .ambientTime *
                    1.8
            ) *
            4;

        ctx.translate(
            0,
            float
        );

        /*
            Sombra.
        */
        ctx.fillStyle =
            "rgba(0,0,0,0.36)";

        ctx.beginPath();

        ctx.ellipse(
            0,
            38,
            42,
            15,
            0,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Corpo sombrio.
        */
        const gradient =
            ctx.createLinearGradient(
                0,
                -75,
                0,
                50
            );

        gradient.addColorStop(
            0,
            "#27212e"
        );

        gradient.addColorStop(
            0.65,
            "#17131d"
        );

        gradient.addColorStop(
            1,
            "rgba(16,12,20,0.18)"
        );

        ctx.fillStyle =
            gradient;

        ctx.beginPath();

        ctx.moveTo(
            -28,
            -36
        );

        ctx.quadraticCurveTo(
            -42,
            10,
            -52,
            48
        );

        ctx.quadraticCurveTo(
            -18,
            34,
            0,
            51
        );

        ctx.quadraticCurveTo(
            20,
            34,
            52,
            48
        );

        ctx.quadraticCurveTo(
            41,
            6,
            28,
            -36
        );

        ctx.closePath();

        ctx.fill();

        /*
            Cabeça/coroa.
        */
        ctx.fillStyle =
            "#211b27";

        ctx.beginPath();

        ctx.arc(
            0,
            -52,
            27,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        ctx.strokeStyle =
            "#4e4157";

        ctx.lineWidth =
            5;

        ctx.beginPath();

        ctx.moveTo(
            -20,
            -69
        );

        ctx.lineTo(
            -28,
            -93
        );

        ctx.lineTo(
            -10,
            -76
        );

        ctx.lineTo(
            0,
            -99
        );

        ctx.lineTo(
            11,
            -76
        );

        ctx.lineTo(
            29,
            -93
        );

        ctx.lineTo(
            20,
            -69
        );

        ctx.stroke();

        /*
            Olhos.
        */
        ctx.shadowColor =
            "#c4bec9";

        ctx.shadowBlur =
            10;

        ctx.fillStyle =
            "rgba(224,220,228,0.85)";

        ctx.fillRect(
            -12,
            -56,
            7,
            2.5
        );

        ctx.fillRect(
            5,
            -56,
            7,
            2.5
        );

        ctx.shadowBlur =
            0;

        /*
            STAGGER VISUAL:
            sem barra numérica horrorosa.
            As rachaduras aumentam.
        */
        if (
            crackRatio >
            0
        ) {
            ctx.strokeStyle =
                `rgba(220,218,225,${
                    0.25 +
                    crackRatio *
                        0.65
                })`;

            ctx.lineWidth =
                1.5 +
                crackRatio *
                    2;

            const crackCount =
                Math.ceil(
                    crackRatio *
                    8
                );

            for (
                let index = 0;
                index < crackCount;
                index += 1
            ) {
                const angle =
                    (
                        index /
                        Math.max(
                            1,
                            crackCount
                        )
                    ) *
                    Math.PI *
                    2;

                const start =
                    25;

                const end =
                    37 +
                    index *
                        2;

                ctx.beginPath();

                ctx.moveTo(
                    Math.cos(
                        angle
                    ) *
                        start,
                    Math.sin(
                        angle
                    ) *
                        start -
                        22
                );

                ctx.lineTo(
                    Math.cos(
                        angle +
                        0.18
                    ) *
                        (
                            start +
                            8
                        ),
                    Math.sin(
                        angle +
                        0.18
                    ) *
                        (
                            start +
                            8
                        ) -
                        22
                );

                ctx.lineTo(
                    Math.cos(
                        angle
                    ) *
                        end,
                    Math.sin(
                        angle
                    ) *
                        end -
                        22
                );

                ctx.stroke();
            }
        }

        if (
            boss.state ===
            V.BOSS_STATE.STUNNED
        ) {
            ctx.strokeStyle =
                "rgba(238,235,232,0.7)";

            ctx.lineWidth =
                4;

            ctx.setLineDash(
                [
                    5,
                    8
                ]
            );

            ctx.beginPath();

            ctx.arc(
                0,
                -20,
                62,
                0,
                Math.PI *
                    2
            );

            ctx.stroke();

            ctx.setLineDash(
                []
            );
        }
    }


    /* ============================================================
       VAELKOR
       ============================================================ */

    function drawVaelkorBoss(
        ctx,
        boss
    ) {
        const float =
            Math.sin(
                renderRuntime
                    .ambientTime *
                    2
            ) *
            7;

        ctx.translate(
            0,
            float
        );

        /*
            Aura do Vazio.
        */
        const aura =
            ctx.createRadialGradient(
                0,
                0,
                10,
                0,
                0,
                85
            );

        aura.addColorStop(
            0,
            "rgba(122,83,146,0.28)"
        );

        aura.addColorStop(
            1,
            "rgba(31,20,40,0)"
        );

        ctx.fillStyle =
            aura;

        ctx.beginPath();

        ctx.arc(
            0,
            0,
            85,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Manto.
        */
        ctx.fillStyle =
            "#2c2235";

        ctx.beginPath();

        ctx.moveTo(
            -24,
            -36
        );

        ctx.lineTo(
            -42,
            48
        );

        ctx.quadraticCurveTo(
            0,
            30,
            42,
            48
        );

        ctx.lineTo(
            24,
            -36
        );

        ctx.closePath();

        ctx.fill();

        /*
            Cabeça.
        */
        ctx.fillStyle =
            "#18141e";

        ctx.beginPath();

        ctx.arc(
            0,
            -47,
            24,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        /*
            Fenda.
        */
        ctx.strokeStyle =
            "#a17aba";

        ctx.shadowColor =
            "#81589b";

        ctx.shadowBlur =
            15;

        ctx.lineWidth =
            4;

        ctx.beginPath();

        ctx.moveTo(
            -12,
            -49
        );

        ctx.quadraticCurveTo(
            0,
            -43,
            12,
            -49
        );

        ctx.stroke();

        ctx.shadowBlur =
            0;

        /*
            Fragmentos orbitais.
        */
        for (
            let index = 0;
            index < 3;
            index += 1
        ) {
            const angle =
                renderRuntime
                    .ambientTime *
                    (
                        0.9 +
                        index *
                            0.12
                    ) +
                index *
                    (
                        Math.PI *
                        2 /
                        3
                    );

            ctx.fillStyle =
                "rgba(132,94,153,0.7)";

            ctx.beginPath();

            ctx.arc(
                Math.cos(
                    angle
                ) *
                    49,
                -16 +
                Math.sin(
                    angle
                ) *
                    22,
                5,
                0,
                Math.PI *
                    2
            );

            ctx.fill();
        }
    }


    /* ============================================================
       ALTAR
       ============================================================ */

    function drawMonarchAltar(
        ctx
    ) {
        const world =
            state.world;

        const altar =
            world
                ?.altar;

        if (
            !altar ||
            !isPointVisible(
                altar.x,
                altar.y,
                200
            )
        ) {
            return;
        }

        const screen =
            worldToScreen(
                altar.x,
                altar.y
            );

        const awakened =
            state.player
                ?.monarch
                ?.defeated;

        const pulse =
            Math.sin(
                renderRuntime
                    .ambientTime *
                    2.2
            );

        ctx.save();

        ctx.translate(
            screen.x,
            screen.y
        );

        /*
            Base.
        */
        ctx.fillStyle =
            "#39343b";

        ctx.beginPath();

        ctx.ellipse(
            0,
            20,
            82,
            35,
            0,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        ctx.strokeStyle =
            "#69616c";

        ctx.lineWidth =
            5;

        ctx.stroke();

        /*
            Degraus.
        */
        ctx.fillStyle =
            "#484248";

        ctx.fillRect(
            -58,
            -5,
            116,
            28
        );

        ctx.fillStyle =
            "#514b52";

        ctx.fillRect(
            -43,
            -28,
            86,
            27
        );

        /*
            Pedra central.
        */
        ctx.fillStyle =
            awakened
                ? "#a5aba9"
                : "#656169";

        ctx.beginPath();

        ctx.moveTo(
            -24,
            -28
        );

        ctx.lineTo(
            -16,
            -92
        );

        ctx.lineTo(
            16,
            -92
        );

        ctx.lineTo(
            24,
            -28
        );

        ctx.closePath();

        ctx.fill();

        /*
            Símbolo.
        */
        ctx.strokeStyle =
            awakened
                ? `rgba(226,232,229,${
                    0.65 +
                    pulse *
                        0.15
                })`
                : "rgba(129,112,138,0.55)";

        ctx.shadowColor =
            awakened
                ? "#e1e8e4"
                : "#70577b";

        ctx.shadowBlur =
            awakened
                ? 20
                : 8;

        ctx.lineWidth =
            3;

        ctx.beginPath();

        ctx.arc(
            0,
            -56,
            14,
            0,
            Math.PI *
                2
        );

        ctx.moveTo(
            0,
            -72
        );

        ctx.lineTo(
            0,
            -40
        );

        ctx.moveTo(
            -13,
            -56
        );

        ctx.lineTo(
            13,
            -56
        );

        ctx.stroke();

        ctx.shadowBlur =
            0;

        ctx.restore();
    }


    /* ============================================================
       DECORAÇÕES
       ============================================================ */

    function drawDecoration(
        ctx,
        decoration
    ) {
        if (
            !decoration ||
            !isPointVisible(
                decoration.x,
                decoration.y,
                150
            )
        ) {
            return;
        }

        switch (
            decoration.type
        ) {
            case "fountain":
                drawFountain(
                    ctx,
                    decoration
                );
                break;

            case "pathUnlockedRune":
                drawPathUnlockedRune(
                    ctx,
                    decoration
                );
                break;

            case "cloud":
            case "skyCloud":
                drawCloud(
                    ctx,
                    decoration
                );
                break;

            case "bed":
                drawBed(
                    ctx,
                    decoration
                );
                break;

            case "table":
            case "archiveTable":
            case "workbench":
                drawTable(
                    ctx,
                    decoration
                );
                break;

            case "bookshelf":
            case "shelves":
                drawShelf(
                    ctx,
                    decoration
                );
                break;

            case "anvil":
                drawAnvil(
                    ctx,
                    decoration
                );
                break;

            case "forgeFire":
                drawForgeFire(
                    ctx,
                    decoration
                );
                break;

            case "crates":
            case "woodStack":
            case "coalPile":
                drawMaterialPile(
                    ctx,
                    decoration
                );
                break;

            case "voidFragmentGlow":
                drawVoidFragmentGlow(
                    ctx,
                    decoration
                );
                break;

            default:
                drawGenericDecoration(
                    ctx,
                    decoration
                );
                break;
        }
    }


    function drawPathUnlockedRune(
        ctx,
        rune
    ) {
        const screen =
            worldToScreen(
                rune.x,
                rune.y
            );

        const pulse =
            1 +
            Math.sin(
                renderRuntime
                    .ambientTime *
                    2.5 +
                finiteNumber(
                    rune.pulse,
                    0
                )
            ) *
                0.08;

        ctx.save();

        ctx.translate(
            screen.x,
            screen.y
        );

        ctx.scale(
            pulse,
            pulse *
                0.55
        );

        ctx.strokeStyle =
            "rgba(104,161,194,0.72)";

        ctx.shadowColor =
            "#5f91ad";

        ctx.shadowBlur =
            13;

        ctx.lineWidth =
            3;

        ctx.beginPath();

        ctx.arc(
            0,
            0,
            28,
            0,
            Math.PI *
                2
        );

        ctx.stroke();

        ctx.beginPath();

        ctx.moveTo(
            -18,
            0
        );

        ctx.lineTo(
            0,
            -18
        );

        ctx.lineTo(
            18,
            0
        );

        ctx.lineTo(
            0,
            18
        );

        ctx.closePath();

        ctx.stroke();

        ctx.shadowBlur =
            0;

        ctx.restore();
    }


