    function drawShelf(
        ctx,
        shelf
    ) {
        const screen =
            worldToScreen(
                shelf.x,
                shelf.y
            );

        const w =
            shelf.w ||
            70;

        const h =
            shelf.h ||
            100;

        ctx.fillStyle =
            "#493429";

        ctx.fillRect(
            screen.x -
                w /
                    2,
            screen.y -
                h /
                    2,
            w,
            h
        );

        for (
            let y = 1;
            y <= 3;
            y += 1
        ) {
            ctx.fillStyle =
                "#2b211c";

            ctx.fillRect(
                screen.x -
                    w /
                        2 +
                    5,
                screen.y -
                    h /
                        2 +
                    y *
                        25,
                w -
                    10,
                4
            );

            for (
                let book = 0;
                book < 5;
                book += 1
            ) {
                const tones = [
                    "#725c54",
                    "#4d6170",
                    "#746a4e",
                    "#604c68"
                ];

                ctx.fillStyle =
                    tones[
                        (
                            book +
                            y
                        ) %
                        tones.length
                    ];

                ctx.fillRect(
                    screen.x -
                        w /
                            2 +
                        9 +
                        book *
                            10,

                    screen.y -
                        h /
                            2 +
                        y *
                            25 -
                        15,

                    7,

                    14
                );
            }
        }
    }


