   function drawForgeFire(
    ctx,
    forge
) {
    const screen =
        worldToScreen(
            forge.x,
            forge.y
        );


    const pulse =
        Math.sin(
            renderRuntime
                .ambientTime *
            7 +
            forge.x *
                0.01
        );


    ctx.save();


    /*
        BASE DE PEDRA.
    */
    ctx.fillStyle =
        "#4d4742";


    roundRectPath(
        ctx,
        screen.x -
            48,
        screen.y -
            5,
        96,
        52,
        9
    );

    ctx.fill();


    ctx.strokeStyle =
        "#26211e";

    ctx.lineWidth =
        4;

    ctx.stroke();


    /*
        BOCA DA FORNALHA.
    */
    ctx.fillStyle =
        "#171210";


    ctx.beginPath();

    ctx.ellipse(
        screen.x,
        screen.y +
            2,
        34,
        16,
        0,
        0,
        Math.PI *
            2
    );

    ctx.fill();


    /*
        PEDRAS.
    */
    ctx.fillStyle =
        "#68605a";


    ctx.fillRect(
        screen.x -
            48,
        screen.y +
            13,
        14,
        30
    );


    ctx.fillRect(
        screen.x +
            34,
        screen.y +
            13,
        14,
        30
    );


    /*
        FOGO EXTERNO.
    */
    ctx.shadowBlur =
        20;

    ctx.shadowColor =
        "#d47a3f";

    ctx.fillStyle =
        "#a84c30";


    ctx.beginPath();

    ctx.moveTo(
        screen.x,
        screen.y -
            31 -
            pulse *
                4
    );

    ctx.quadraticCurveTo(
        screen.x -
            17,
        screen.y -
            6,
        screen.x,
        screen.y +
            11
    );

    ctx.quadraticCurveTo(
        screen.x +
            17,
        screen.y -
            6,
        screen.x,
        screen.y -
            31 -
            pulse *
                4
    );

    ctx.fill();


    /*
        FOGO INTERNO.
    */
    ctx.fillStyle =
        "#efad52";


    ctx.beginPath();

    ctx.moveTo(
        screen.x,
        screen.y -
            20 -
            pulse *
                2
    );

    ctx.quadraticCurveTo(
        screen.x -
            8,
        screen.y -
            2,
        screen.x,
        screen.y +
            7
    );

    ctx.quadraticCurveTo(
        screen.x +
            8,
        screen.y -
            2,
        screen.x,
        screen.y -
            20 -
            pulse *
                2
    );

    ctx.fill();


    ctx.shadowBlur =
        0;


    ctx.restore();
}


