    function drawStaticDecorations(
        ctx
    ) {
        const world =
            state.world;

        if (!world) {
            return;
        }

        for (
            const decoration of
            safeArray(
                world.decorations
            )
        ) {
            if (
                decoration.depthSorted
            ) {
                continue;
            }

            drawDecoration(
                ctx,
                decoration
            );
        }
    }


