    /* ============================================================
       PROJÉTEIS
       ============================================================ */

    function drawProjectiles(
        ctx
    ) {
        const world =
            state.world;

        if (!world) {
            return;
        }

        for (
            const projectile of
            safeArray(
                world.projectiles
            )
        ) {
            if (
                projectile.dead ||
                !isPointVisible(
                    projectile.x,
                    projectile.y,
                    50
                )
            ) {
                continue;
            }

            const screen =
                worldToScreen(
                    projectile.x,
                    projectile.y
                );

            ctx.save();

            ctx.shadowColor =
                projectile.color;

            ctx.shadowBlur =
                12;

            ctx.fillStyle =
                projectile.color;

            ctx.beginPath();

            ctx.arc(
                screen.x,
                screen.y,
                projectile.radius,
                0,
                Math.PI *
                    2
            );

            ctx.fill();

            /*
                Rastro.
            */
            const velocityLength =
                Math.hypot(
                    projectile.vx,
                    projectile.vy
                ) ||
                1;

            const nx =
                projectile.vx /
                velocityLength;

            const ny =
                projectile.vy /
                velocityLength;

            const gradient =
                ctx.createLinearGradient(
                    screen.x,
                    screen.y,
                    screen.x -
                        nx *
                            35,
                    screen.y -
                        ny *
                            35
                );

            gradient.addColorStop(
                0,
                colorWithAlpha(
                    projectile.color,
                    0.65
                )
            );

            gradient.addColorStop(
                1,
                colorWithAlpha(
                    projectile.color,
                    0
                )
            );

            ctx.strokeStyle =
                gradient;

            ctx.lineWidth =
                projectile.radius *
                1.3;

            ctx.beginPath();

            ctx.moveTo(
                screen.x,
                screen.y
            );

            ctx.lineTo(
                screen.x -
                    nx *
                        35,
                screen.y -
                    ny *
                        35
            );

            ctx.stroke();

            ctx.shadowBlur =
                0;

            ctx.restore();
        }
    }


    /* ============================================================
       HAZARDS / TELEGRAPHS
       ============================================================ */

    function drawHazards(
        ctx
    ) {
        const world =
            state.world;

        if (!world) {
            return;
        }

        for (
            const hazard of
            safeArray(
                world.hazards
            )
        ) {
            if (
                hazard.dead
            ) {
                continue;
            }

            const screen =
                worldToScreen(
                    hazard.x,
                    hazard.y
                );

            const telegraphRatio =
                hazard.active
                    ? 1
                    : clamp(
                        hazard.timer /
                        Math.max(
                            0.001,
                            hazard.telegraph
                        ),
                        0,
                        1
                    );

            ctx.save();

            if (
                hazard.type ===
                "beam"
            ) {
                ctx.translate(
                    screen.x,
                    screen.y
                );

                ctx.rotate(
                    hazard.angle
                );

                ctx.fillStyle =
                    hazard.active
                        ? colorWithAlpha(
                            hazard.color,
                            0.52
                        )
                        : colorWithAlpha(
                            hazard.color,
                            0.12 +
                                telegraphRatio *
                                    0.18
                        );

                ctx.fillRect(
                    0,
                    -hazard.width /
                        2,
                    hazard.length,
                    hazard.width
                );

                ctx.strokeStyle =
                    colorWithAlpha(
                        hazard.color,
                        0.5
                    );

                ctx.lineWidth =
                    2;

                ctx.strokeRect(
                    0,
                    -hazard.width /
                        2,
                    hazard.length,
                    hazard.width
                );
            } else {
                ctx.fillStyle =
                    hazard.active
                        ? colorWithAlpha(
                            hazard.color,
                            0.4
                        )
                        : colorWithAlpha(
                            hazard.color,
                            0.08 +
                                telegraphRatio *
                                    0.15
                        );

                ctx.strokeStyle =
                    colorWithAlpha(
                        hazard.color,
                        0.55
                    );

                ctx.lineWidth =
                    3;

                ctx.beginPath();

                ctx.arc(
                    screen.x,
                    screen.y,
                    hazard.radius,
                    0,
                    Math.PI *
                        2
                );

                ctx.fill();

                ctx.stroke();
            }

            ctx.restore();
        }
    }


    /* ============================================================
       EFEITOS TRANSITÓRIOS
       ============================================================ */

    function drawTransientEffects(
        ctx
    ) {
        for (
            const effect of
            gameplayRuntime
                .transientEffects
        ) {
            const screen =
                worldToScreen(
                    finiteNumber(
                        effect.x,
                        0
                    ),
                    finiteNumber(
                        effect.y,
                        0
                    )
                );

            const progress =
                1 -
                clamp(
                    effect.timer /
                    effect.maxTimer,
                    0,
                    1
                );

            const alpha =
                1 -
                progress;

            ctx.save();

            ctx.globalAlpha =
                alpha;
switch (
    effect.type
) {
    case "dashV1Trail":
    case "dashV1Start":
    case "dashV1End":
        drawDashEffect(
            ctx,
            screen,
            effect,
            progress,
            false
        );
        break;


    case "dashV2Trail":
    case "dashV2Start":
    case "dashV2End":
    case "dashV2Unlock":
        drawDashEffect(
            ctx,
            screen,
            effect,
            progress,
            true
        );
        break;


    case "hitSpark":
    case "playerHit":
    case "voidHit":
    case "projectileImpact":
        drawHitEffect(
            ctx,
            screen,
            effect,
            progress
        );
        break;


    case "groundImpact":
    case "hazardActivate":
        drawRingEffect(
            ctx,
            screen,
            effect,
            progress
        );
        break;


    /*
        ATAQUE BÁSICO.

        Theron = espada.
        Grumgar = impacto no chão.
        Zephyr = corte de fenda.
        Kaelion/Lirael = partículas.
    */
    case "basicAttack":
        drawBasicAttackEffect(
            ctx,
            screen,
            effect,
            progress
        );
        break;


    /*
        THERON / ZEPHYR.
    */
    case "guardianStrike":
    case "guardianCharge":
    case "adaptiveCut":
    case "riftStep":
        drawSkillSlashEffect(
            ctx,
            screen,
            effect,
            progress
        );
        break;


    /*
        GRUMGAR.
    */
    case "crushingBlow":
    case "stoneRoar":
    case "earthBreaker":
        drawGroundCrackSkillEffect(
            ctx,
            screen,
            effect,
            progress
        );
        break;


    /*
        BUFFS.
    */
    case "ironStance":
    case "adaptiveForm":
        drawSkillAuraEffect(
            ctx,
            screen,
            effect,
            progress
        );
        break;


    /*
        KAELION / LIRAEL.
    */
    case "kaelionRay":
    case "arcaneCircle":
    case "memoryExplosion":
    case "vitalLight":
    case "fairyBlast":
    case "lightRain":
        drawMagicSparkEffect(
            ctx,
            screen,
            effect,
            progress
        );
        break;


    case "monarchCrack":
    case "monarchStaggerBreak":
    case "monarchRecover":
        drawMonarchEffect(
            ctx,
            screen,
            effect,
            progress
        );
        break;


    case "monarchDissolve":
    case "altarSoulAbsorb":
        drawMonarchDeathEffect(
            ctx,
            screen,
            effect,
            progress
        );
        break;


    case "pathBossFade":
    case "enemyDeath":
        drawDeathParticles(
            ctx,
            screen,
            effect,
            progress
        );
        break;

    default:
        drawHitEffect(
            ctx,
            screen,
            effect,
            progress
        );
        break;
}

            ctx.restore();
        }
    }


    function drawDashEffect(
        ctx,
        screen,
        effect,
        progress,
        voidVersion
    ) {
        const radius =
            18 +
            progress *
                42;

        ctx.strokeStyle =
            voidVersion
                ? "rgba(107,73,133,0.68)"
                : "rgba(238,244,246,0.72)";

        ctx.lineWidth =
            5 *
            (
                1 -
                progress *
                    0.6
            );

        ctx.beginPath();

        ctx.ellipse(
            screen.x,
            screen.y,
            radius,
            radius *
                0.42,
            0,
            0,
            Math.PI *
                2
        );

        ctx.stroke();
    }


    function drawHitEffect(
        ctx,
        screen,
        effect,
        progress
    ) {
        const color =
            effect.color ||
            "#d9c8aa";

        ctx.strokeStyle =
            colorWithAlpha(
                color,
                0.8
            );

        ctx.lineWidth =
            3;

        for (
            let index = 0;
            index < 6;
            index += 1
        ) {
            const angle =
                (
                    index /
                    6
                ) *
                Math.PI *
                2;

            const start =
                progress *
                10;

            const end =
                8 +
                progress *
                    28;

            ctx.beginPath();

            ctx.moveTo(
                screen.x +
                    Math.cos(
                        angle
                    ) *
                        start,
                screen.y +
                    Math.sin(
                        angle
                    ) *
                        start
            );

            ctx.lineTo(
                screen.x +
                    Math.cos(
                        angle
                    ) *
                        end,
                screen.y +
                    Math.sin(
                        angle
                    ) *
                        end
            );

            ctx.stroke();
        }
    }


    function drawRingEffect(
        ctx,
        screen,
        effect,
        progress
    ) {
        const radius =
            finiteNumber(
                effect.radius,
                80
            ) *
            (
                0.25 +
                progress *
                    0.75
            );

        ctx.strokeStyle =
            colorWithAlpha(
                effect.color ||
                    "#b7a58b",
                0.7
            );

        ctx.lineWidth =
            4 *
            (
                1 -
                progress *
                    0.7
            );

        ctx.beginPath();

        ctx.ellipse(
            screen.x,
            screen.y,
            radius,
            radius *
                0.46,
            0,
            0,
            Math.PI *
                2
        );

        ctx.stroke();
    }


    function drawMonarchEffect(
        ctx,
        screen,
        effect,
        progress
    ) {
        ctx.strokeStyle =
            `rgba(232,229,235,${
                0.8 *
                (
                    1 -
                    progress
                )
            })`;

        ctx.lineWidth =
            4;

        const radius =
            35 +
            progress *
                75;

        ctx.setLineDash(
            [
                8,
                9
            ]
        );

        ctx.beginPath();

        ctx.arc(
            screen.x,
            screen.y,
            radius,
            0,
            Math.PI *
                2
        );

        ctx.stroke();

        ctx.setLineDash(
            []
        );
    }


    function drawMonarchDeathEffect(
        ctx,
        screen,
        effect,
        progress
    ) {
        const target =
            effect.targetX !==
            undefined
                ? worldToScreen(
                    effect.targetX,
                    effect.targetY
                )
                : null;

        const count =
            effect.count ||
            24;

        for (
            let index = 0;
            index < count;
            index += 1
        ) {
            const seed =
                index *
                12.9898;

            const angle =
                seed %
                (
                    Math.PI *
                    2
                );

            const radius =
                20 +
                (
                    index %
                    7
                ) *
                    7;

            let x =
                screen.x +
                Math.cos(
                    angle
                ) *
                    radius;

            let y =
                screen.y +
                Math.sin(
                    angle
                ) *
                    radius;

            if (target) {
                x =
                    lerp(
                        x,
                        target.x,
                        progress
                    );

                y =
                    lerp(
                        y,
                        target.y,
                        progress
                    );
            } else {
                y -=
                    progress *
                    70;
            }

            ctx.fillStyle =
                `rgba(222,224,220,${
                    0.7 *
                    (
                        1 -
                        progress
                    )
                })`;

            ctx.beginPath();

            ctx.arc(
                x,
                y,
                2 +
                    (
                        index %
                        3
                    ),
                0,
                Math.PI *
                    2
            );

            ctx.fill();
        }
    }


    function drawDeathParticles(
        ctx,
        screen,
        effect,
        progress
    ) {
        const count =
            effect.particleCount ||
            8;

        for (
            let index = 0;
            index < count;
            index += 1
        ) {
            const angle =
                (
                    index /
                    count
                ) *
                Math.PI *
                2;

            const radius =
                progress *
                35;

            ctx.fillStyle =
                colorWithAlpha(
                    effect.color ||
                    "#c8c0b4",
                    0.75 *
                        (
                            1 -
                            progress
                        )
                );

            ctx.beginPath();

            ctx.arc(
                screen.x +
                    Math.cos(
                        angle
                    ) *
                        radius,

                screen.y -
                    progress *
                        30 +
                    Math.sin(
                        angle
                    ) *
                        radius *
                        0.45,

                3,

                0,

                Math.PI *
                    2
            );

            ctx.fill();
        }
    }

   function getEffectFacingAngle(
    effect
) {
    const aimX =
        Number(
            effect?.aimX
        );

    const aimY =
        Number(
            effect?.aimY
        );


    if (
        Number.isFinite(
            aimX
        ) &&
        Number.isFinite(
            aimY
        ) &&
        (
            Math.abs(
                aimX
            ) +
            Math.abs(
                aimY
            )
        ) >
            0.001
    ) {
        return Math.atan2(
            aimY,
            aimX
        );
    }


    switch (
        state.player
            ?.facing
    ) {
        case "left":
            return Math.PI;

        case "up":
            return -Math.PI /
                2;

        case "down":
            return Math.PI /
                2;

        case "right":
        default:
            return 0;
    }
}


function drawBasicAttackEffect(
    ctx,
    screen,
    effect,
    progress
) {
    const characterId =
        effect.characterId ||
        state.player
            ?.characterId;


    /*
        CAVALEIRO.
    */
    if (
        characterId ===
        "theron"
    ) {
        drawSkillSlashEffect(
            ctx,
            screen,
            {
                ...effect,
                characterId:
                    "theron"
            },
            progress
        );

        return;
    }


    /*
        TROLL.
    */
    if (
        characterId ===
        "grumgar"
    ) {
        drawGroundCrackSkillEffect(
            ctx,
            screen,
            {
                ...effect,
                radius:
                    70
            },
            progress
        );

        return;
    }


    /*
        TRANSMORFO.
    */
    if (
        characterId ===
        "zephyr"
    ) {
        drawSkillSlashEffect(
            ctx,
            screen,
            {
                ...effect,
                characterId:
                    "zephyr"
            },
            progress
        );

        return;
    }


    /*
        MAGO / FADA.
    */
    const color =
        characterId ===
        "lirael"
            ? "#f0a4d2"
            : "#ed8a3f";


    ctx.strokeStyle =
        colorWithAlpha(
            color,
            0.85 *
            (
                1 -
                progress
            )
        );

    ctx.lineWidth =
        2.2;


    const angle =
        getEffectFacingAngle(
            effect
        );


    for (
        let index = -2;
        index <= 2;
        index += 1
    ) {
        const spread =
            angle +
            index *
                0.15;

        const start =
            14 +
            progress *
                7;

        const end =
            28 +
            progress *
                28;


        ctx.beginPath();

        ctx.moveTo(
            screen.x +
                Math.cos(
                    spread
                ) *
                start,

            screen.y +
                Math.sin(
                    spread
                ) *
                start
        );

        ctx.lineTo(
            screen.x +
                Math.cos(
                    spread
                ) *
                end,

            screen.y +
                Math.sin(
                    spread
                ) *
                end
        );

        ctx.stroke();
    }
}


function drawSkillSlashEffect(
    ctx,
    screen,
    effect,
    progress
) {
    const voidStyle =
        effect.type ===
            "adaptiveCut" ||
        effect.type ===
            "riftStep" ||
        effect.characterId ===
            "zephyr";


    const color =
        voidStyle
            ? "#a17bd0"
            : "#d7dbdc";


    const angle =
        getEffectFacingAngle(
            effect
        );


    ctx.save();

    ctx.translate(
        screen.x,
        screen.y
    );

    ctx.rotate(
        angle
    );


    ctx.strokeStyle =
        colorWithAlpha(
            color,
            0.9 *
            (
                1 -
                progress
            )
        );

    ctx.lineCap =
        "round";


    for (
        let index = 0;
        index < 3;
        index += 1
    ) {
        ctx.lineWidth =
            Math.max(
                1,
                5 -
                index
            ) *
            (
                1 -
                progress *
                    0.55
            );


        const radius =
            35 +
            index *
                8 +
            progress *
                25;


        ctx.beginPath();

        ctx.arc(
            0,
            0,
            radius,
            -0.92,
            0.92
        );

        ctx.stroke();
    }


    if (
        voidStyle
    ) {
        ctx.strokeStyle =
            `rgba(91,55,119,${
                0.55 *
                (
                    1 -
                    progress
                )
            })`;

        ctx.lineWidth =
            2;

        ctx.beginPath();

        ctx.moveTo(
            20,
            -22
        );

        ctx.lineTo(
            65 +
                progress *
                    20,
            3
        );

        ctx.stroke();
    }


    ctx.restore();
}


function drawGroundCrackSkillEffect(
    ctx,
    screen,
    effect,
    progress
) {
    const radius =
        Number(
            effect.radius
        ) ||
        100;


    const currentRadius =
        radius *
        (
            0.25 +
            progress *
                0.75
        );


    ctx.strokeStyle =
        `rgba(151,143,105,${
            0.85 *
            (
                1 -
                progress
            )
        })`;


    ctx.lineWidth =
        Math.max(
            1,
            4 -
            progress *
                2.5
        );


    for (
        let index = 0;
        index < 9;
        index += 1
    ) {
        const angle =
            (
                index /
                9
            ) *
            Math.PI *
            2;


        const middle =
            currentRadius *
            0.55;


        ctx.beginPath();

        ctx.moveTo(
            screen.x,
            screen.y
        );


        ctx.lineTo(
            screen.x +
                Math.cos(
                    angle +
                    0.14
                ) *
                middle,

            screen.y +
                Math.sin(
                    angle +
                    0.14
                ) *
                middle *
                0.62
        );


        ctx.lineTo(
            screen.x +
                Math.cos(
                    angle
                ) *
                currentRadius,

            screen.y +
                Math.sin(
                    angle
                ) *
                currentRadius *
                0.62
        );


        ctx.stroke();
    }


    /*
        Poeira curta.
    */
    for (
        let index = 0;
        index < 6;
        index += 1
    ) {
        const angle =
            (
                index /
                6
            ) *
            Math.PI *
            2;

        const distanceAmount =
            progress *
            currentRadius *
            0.7;


        ctx.fillStyle =
            `rgba(132,119,88,${
                0.32 *
                (
                    1 -
                    progress
                )
            })`;

        ctx.beginPath();

        ctx.arc(
            screen.x +
                Math.cos(
                    angle
                ) *
                distanceAmount,

            screen.y +
                Math.sin(
                    angle
                ) *
                distanceAmount *
                0.45,

            3,
            0,
            Math.PI *
                2
        );

        ctx.fill();
    }
}


function drawSkillAuraEffect(
    ctx,
    screen,
    effect,
    progress
) {
    const voidStyle =
        effect.type ===
        "adaptiveForm";


    const color =
        voidStyle
            ? "#9b79bd"
            : "#cbd3d5";


    ctx.strokeStyle =
        colorWithAlpha(
            color,
            0.75 *
            (
                1 -
                progress
            )
        );


    ctx.lineWidth =
        3;


    const height =
        44 +
        progress *
            18;


    /*
        Três arcos verticais,
        não uma bola.
    */
    for (
        let index = -1;
        index <= 1;
        index += 1
    ) {
        ctx.beginPath();

        ctx.moveTo(
            screen.x +
                index *
                    14,
            screen.y +
                24
        );

        ctx.quadraticCurveTo(
            screen.x +
                index *
                    22,
            screen.y -
                height *
                    0.45,

            screen.x +
                index *
                    10,
            screen.y -
                height
        );

        ctx.stroke();
    }
}


function drawMagicSparkEffect(
    ctx,
    screen,
    effect,
    progress
) {
    const colors = {
        kaelionRay:
            "#f29a4f",

        arcaneCircle:
            "#ed9350",

        memoryExplosion:
            "#ffb16a",

        vitalLight:
            "#f2b3dc",

        fairyBlast:
            "#f2a6db",

        lightRain:
            "#f2a7d8"
    };


    const color =
        colors[
            effect.type
        ] ||
        effect.color ||
        "#dfcfb6";


    const radius =
        Number(
            effect.radius
        ) ||
        80;


    ctx.strokeStyle =
        colorWithAlpha(
            color,
            0.82 *
            (
                1 -
                progress
            )
        );


    ctx.lineWidth =
        2;


    for (
        let index = 0;
        index < 12;
        index += 1
    ) {
        const angle =
            (
                index /
                12
            ) *
            Math.PI *
            2;


        const start =
            8 +
            progress *
                radius *
                0.2;


        const end =
            18 +
            progress *
                radius *
                0.75;


        ctx.beginPath();

        ctx.moveTo(
            screen.x +
                Math.cos(
                    angle
                ) *
                start,

            screen.y +
                Math.sin(
                    angle
                ) *
                start *
                0.7
        );


        ctx.lineTo(
            screen.x +
                Math.cos(
                    angle
                ) *
                end,

            screen.y +
                Math.sin(
                    angle
                ) *
                end *
                0.7
        );


        ctx.stroke();
    }
}

    function drawGenericEffect(
        ctx,
        screen,
        effect,
        progress
    ) {
        ctx.strokeStyle =
            colorWithAlpha(
                effect.color ||
                    "#d6cbb7",
                0.6 *
                    (
                        1 -
                        progress
                    )
            );

        ctx.lineWidth =
            3;

        ctx.beginPath();

        ctx.arc(
            screen.x,
            screen.y,
            15 +
                progress *
                    35,
            0,
            Math.PI *
                2
        );

        ctx.stroke();
    }


    /* ============================================================
       ILUMINAÇÃO COM OCLUSÃO REAL

       O objetivo:
       - escuridão fica em canvas separado;
       - luz é recortada no offscreen;
       - paredes blocksLight interrompem raios;
       - nada de destination-out no canvas principal.
       ============================================================ */

    function getLightBlockingRects(
        world =
            state.world
    ) {
        if (!world) {
            return [];
        }

        const blockers =
            [];

        for (
            const obstacle of
            safeArray(
                world.obstacles
            )
        ) {
            if (
                obstacle.blocksLight &&
                obstacle.shape !==
                    "circle"
            ) {
                blockers.push({
                    x:
                        obstacle.x,

                    y:
                        obstacle.y,

                    w:
                        obstacle.w,

                    h:
                        obstacle.h
                });
            }
        }

        for (
            const wall of
            safeArray(
                world.walls
            )
        ) {
            if (
                wall.blocksLight !==
                false
            ) {
                blockers.push({
                    x:
                        wall.x,

                    y:
                        wall.y,

                    w:
                        wall.w,

                    h:
                        wall.h
                });
            }
        }

        return blockers;
    }


    function rayRectIntersectionDistance(
        ox,
        oy,
        dx,
        dy,
        rect,
        maxDistance
    ) {
        let tMin =
            0;

        let tMax =
            maxDistance;

        const axes = [
            {
                origin:
                    ox,
                direction:
                    dx,
                min:
                    rect.x,
                max:
                    rect.x +
                    rect.w
            },

            {
                origin:
                    oy,
                direction:
                    dy,
                min:
                    rect.y,
                max:
                    rect.y +
                    rect.h
            }
        ];

        for (
            const axis of
            axes
        ) {
            if (
                Math.abs(
                    axis.direction
                ) <
                0.000001
            ) {
                if (
                    axis.origin <
                        axis.min ||
                    axis.origin >
                        axis.max
                ) {
                    return null;
                }

                continue;
            }

            let t1 =
                (
                    axis.min -
                    axis.origin
                ) /
                axis.direction;

            let t2 =
                (
                    axis.max -
                    axis.origin
                ) /
                axis.direction;

            if (
                t1 >
                t2
            ) {
                const temp =
                    t1;

                t1 =
                    t2;

                t2 =
                    temp;
            }

            tMin =
                Math.max(
                    tMin,
                    t1
                );

            tMax =
                Math.min(
                    tMax,
                    t2
                );

            if (
                tMin >
                tMax
            ) {
                return null;
            }
        }

        if (
            tMin <
            0
        ) {
            if (
                tMax <
                0
            ) {
                return null;
            }

            return tMax;
        }

        return tMin;
    }


    function castLightRay(
        ox,
        oy,
        angle,
        maxDistance,
        blockers
    ) {
        const dx =
            Math.cos(
                angle
            );

        const dy =
            Math.sin(
                angle
            );

        let nearest =
            maxDistance;

        for (
            const rect of
            blockers
        ) {
            const result =
                rayRectIntersectionDistance(
                    ox,
                    oy,
                    dx,
                    dy,
                    rect,
                    nearest
                );

            if (
                result !==
                    null &&
                result <
                    nearest
            ) {
                nearest =
                    Math.max(
                        0,
                        result -
                            2
                    );
            }
        }

        return {
            x:
                ox +
                dx *
                    nearest,

            y:
                oy +
                dy *
                    nearest,

            distance:
                nearest,

            angle
        };
    }


    function buildVisibilityPolygon(
        x,
        y,
        radius,
        world =
            state.world
    ) {
        const blockers =
            getLightBlockingRects(
                world
            );

        const points =
            [];

        /*
            Raios regulares.
        */
        const baseRayCount =
            150;

        for (
            let index = 0;
            index < baseRayCount;
            index += 1
        ) {
            const angle =
                (
                    index /
                    baseRayCount
                ) *
                Math.PI *
                2;

            points.push(
                castLightRay(
                    x,
                    y,
                    angle,
                    radius,
                    blockers
                )
            );
        }

        /*
            Raios extras nos cantos das paredes.
            Isso deixa sombra mais precisa.
        */
        for (
            const rect of
            blockers
        ) {
            const corners = [
                [
                    rect.x,
                    rect.y
                ],

                [
                    rect.x +
                        rect.w,
                    rect.y
                ],

                [
                    rect.x,
                    rect.y +
                        rect.h
                ],

                [
                    rect.x +
                        rect.w,
                    rect.y +
                        rect.h
                ]
            ];

            for (
                const [
                    cx,
                    cy
                ] of
                corners
            ) {
                if (
                    distance(
                        x,
                        y,
                        cx,
                        cy
                    ) >
                    radius +
                        80
                ) {
                    continue;
                }

                const angle =
                    Math.atan2(
                        cy -
                            y,
                        cx -
                            x
                    );

                for (
                    const offset of
                    [
                        -0.0008,
                        0,
                        0.0008
                    ]
                ) {
                    points.push(
                        castLightRay(
                            x,
                            y,
                            angle +
                                offset,
                            radius,
                            blockers
                        )
                    );
                }
            }
        }

        points.sort(
            (
                a,
                b
            ) =>
                a.angle -
                b.angle
        );

        renderRuntime
            .frameStats
            .lightRays =
            points.length;

        renderRuntime.lanternPolygon =
            points;

        return points;
    }


    function drawDarknessLayer(
        mainCtx
    ) {
        const player =
            state.player;

        const world =
            state.world;

        if (
            !player ||
            !world
        ) {
            return;
        }

        const lighting =
            getLanternLightingState(
                player.x,
                player.y,
                world
            );

        /*
            SALA DO ALTAR:
            iluminação normal.

            A lanterna some visualmente aqui.
        */
        if (
            !lighting.darkness
        ) {
            return;
        }

        const canvas =
            renderRuntime
                .darknessCanvas;

        const ctx =
            renderRuntime
                .darknessCtx;

        if (
            !canvas ||
            !ctx
        ) {
            return;
        }

        const dpr =
            renderRuntime.dpr;

        ctx.save();

        ctx.setTransform(
            dpr,
            0,
            0,
            dpr,
            0,
            0
        );

        ctx.clearRect(
            0,
            0,
            renderRuntime.width,
            renderRuntime.height
        );

        /*
            Base escura.
        */
        const baseDarkness =
            world.id ===
            "voidDungeon"
                ? 0.94
                : 0.91;

        ctx.fillStyle =
            `rgba(5,5,9,${baseDarkness})`;

        ctx.fillRect(
            0,
            0,
            renderRuntime.width,
            renderRuntime.height
        );

        const radius =
            lighting.lantern
                ? finiteNumber(
                    GAME_CONFIG
                        .lanternVisionRadius,
                    255
                )
                : finiteNumber(
                    GAME_CONFIG
                        .noLanternVisionRadius,
                    70
                );

        const polygon =
            buildVisibilityPolygon(
                player.x,
                player.y,
                radius,
                world
            );

        if (
            polygon.length <
            3
        ) {
            ctx.restore();
            return;
        }

        const playerScreen =
            worldToScreen(
                player.x,
                player.y
            );

        /*
            IMPORTANTE:
            destination-out apenas no offscreen.
        */
        ctx.globalCompositeOperation =
            "destination-out";

        ctx.beginPath();

        const first =
            worldToScreen(
                polygon[0].x,
                polygon[0].y
            );

        ctx.moveTo(
            first.x,
            first.y
        );

        for (
            let index = 1;
            index <
            polygon.length;
            index += 1
        ) {
            const point =
                worldToScreen(
                    polygon[index].x,
                    polygon[index].y
                );

            ctx.lineTo(
                point.x,
                point.y
            );
        }

        ctx.closePath();

        ctx.fillStyle =
            "rgba(0,0,0,0.92)";

        ctx.fill();

        /*
            Núcleo suave da luz.
        */
        const gradient =
            ctx.createRadialGradient(
                playerScreen.x,
                playerScreen.y,
                radius *
                    0.15,

                playerScreen.x,
                playerScreen.y,
                radius
            );

        gradient.addColorStop(
            0,
            "rgba(0,0,0,1)"
        );

        gradient.addColorStop(
            0.55,
            "rgba(0,0,0,0.72)"
        );

        gradient.addColorStop(
            1,
            "rgba(0,0,0,0)"
        );

        ctx.fillStyle =
            gradient;

        ctx.beginPath();

        ctx.arc(
            playerScreen.x,
            playerScreen.y,
            radius,
            0,
            Math.PI *
                2
        );

        ctx.fill();

        ctx.globalCompositeOperation =
            "source-over";

        /*
            Pequeno tom quente da Lanterna Antiga.
        */
        if (
            lighting.lantern
        ) {
            const warm =
                ctx.createRadialGradient(
                    playerScreen.x,
                    playerScreen.y,
                    0,

                    playerScreen.x,
                    playerScreen.y,
                    radius *
                        0.62
                );

            warm.addColorStop(
                0,
                "rgba(195,164,103,0.07)"
            );

            warm.addColorStop(
                1,
                "rgba(195,164,103,0)"
            );

            ctx.fillStyle =
                warm;

            ctx.beginPath();

            ctx.arc(
                playerScreen.x,
                playerScreen.y,
                radius *
                    0.62,
                0,
                Math.PI *
                    2
            );

            ctx.fill();
        }

        ctx.restore();

        mainCtx.drawImage(
            canvas,
            0,
            0,
            canvas.width,
            canvas.height,

            0,
            0,
            renderRuntime.width,
            renderRuntime.height
        );
    }


    /* ============================================================
       MINIMAPA

       Moldura SEMPRE existe.

       Sem comprar:
       SEM SINAL.

       Void:
       SEM SINAL.

       Labirinto:
       só mostra corredores explorados.
       ============================================================ */

    function drawMinimap(
        ctx
    ) {
        const player =
            state.player;

        const world =
            state.world;

        if (
            !player ||
            !world
        ) {
            return;
        }

        const width =
            205;

        const height =
            155;

        const x =
            renderRuntime.width -
                width -
                22;

        const y =
            22;

        ctx.save();

        /*
            Sombra.
        */
        ctx.fillStyle =
            "rgba(0,0,0,0.38)";

        roundRectPath(
            ctx,
            x +
                5,
            y +
                6,
            width,
            height,
            12
        );

        ctx.fill();

        /*
            Moldura.
        */
        ctx.fillStyle =
            "rgba(17,16,21,0.88)";

        roundRectPath(
            ctx,
            x,
            y,
            width,
            height,
            12
        );

        ctx.fill();

        ctx.strokeStyle =
            "rgba(185,164,119,0.42)";

        ctx.lineWidth =
            2;

        ctx.stroke();

        ctx.font =
            "600 10px serif";

        ctx.fillStyle =
            "rgba(215,203,178,0.78)";

        ctx.textAlign =
            "left";

        ctx.fillText(
            REGION_META[
                state.area
            ]?.name ||
                state.area
                    ?.toUpperCase() ||
                "LOCALIZAÇÃO",

            x +
                12,

            y +
                17
        );

        const hasSignal =
            isMinimapSignalAvailable(
                state.area,
                player
            );

        if (
            !hasSignal
        ) {
            ctx.textAlign =
                "center";

            ctx.fillStyle =
                "rgba(173,164,160,0.72)";

            ctx.font =
                "700 13px serif";

            ctx.fillText(
                "SEM SINAL",
                x +
                    width /
                        2,
                y +
                    height /
                        2 -
                    4
            );

            ctx.font =
                "10px serif";

            ctx.fillStyle =
                "rgba(140,134,132,0.65)";

            ctx.fillText(
                state.area ===
                    "voidDungeon"
                    ? "LOCALIZAÇÃO DESCONHECIDA"
                    : player.minimapOwned
                        ? "SINAL INDISPONÍVEL"
                        : "ADQUIRA O MINIMAPA",

                x +
                    width /
                        2,

                y +
                    height /
                        2 +
                    15
            );

            ctx.restore();

            return;
        }

        const mapX =
            x +
                10;

        const mapY =
            y +
                25;

        const mapW =
            width -
                20;

        const mapH =
            height -
                35;

        ctx.save();

        ctx.beginPath();

        ctx.rect(
            mapX,
            mapY,
            mapW,
            mapH
        );

        ctx.clip();

        ctx.fillStyle =
            "rgba(38,43,40,0.82)";

        ctx.fillRect(
            mapX,
            mapY,
            mapW,
            mapH
        );

        const scaleX =
            mapW /
            world.width;

        const scaleY =
            mapH /
            world.height;

        /*
            Caminhos.
        */
        for (
            const path of
            safeArray(
                world.paths
            )
        ) {
            if (
                world.id ===
                "monarchMaze" &&
                !isMazePathExplored(
                    path,
                    world
                )
            ) {
                continue;
            }

            ctx.fillStyle =
                "rgba(163,151,126,0.54)";

            ctx.fillRect(
                mapX +
                    path.x *
                        scaleX,

                mapY +
                    path.y *
                        scaleY,

                Math.max(
                    1,
                    path.w *
                        scaleX
                ),

                Math.max(
                    1,
                    path.h *
                        scaleY
                )
            );
        }

        /*
            Áreas importantes só se já foram alcançadas/
            conhecidas no mapa atual.
        */
        for (
            const exit of
            safeArray(
                world.exits
            )
        ) {
            if (
                !exit.unlocked &&
                !exit.discovered
            ) {
                continue;
            }

            ctx.fillStyle =
                "rgba(117,157,180,0.8)";

            ctx.beginPath();

            ctx.arc(
                mapX +
                    (
                        exit.x +
                        exit.w /
                            2
                    ) *
                        scaleX,

                mapY +
                    (
                        exit.y +
                        exit.h /
                            2
                    ) *
                        scaleY,

                2.5,

                0,

                Math.PI *
                    2
            );

            ctx.fill();
        }

        /*
            Player.
        */
        ctx.fillStyle =
            "#f0e2b9";

        ctx.shadowColor =
            "#f0e2b9";

        ctx.shadowBlur =
            5;

        ctx.beginPath();

        ctx.arc(
            mapX +
                player.x *
                    scaleX,

            mapY +
                player.y *
                    scaleY,

            3.4,

            0,

            Math.PI *
                2
        );

        ctx.fill();

        ctx.shadowBlur =
            0;

        ctx.restore();

        ctx.restore();
    }


    function isMazePathExplored(
        path,
        world
    ) {
        if (
            world.id !==
            "monarchMaze"
        ) {
            return true;
        }

        const sampleCount =
            5;

        for (
            let xIndex = 0;
            xIndex < sampleCount;
            xIndex += 1
        ) {
            for (
                let yIndex = 0;
                yIndex < sampleCount;
                yIndex += 1
            ) {
                const x =
                    path.x +
                    path.w *
                        (
                            xIndex +
                            0.5
                        ) /
                        sampleCount;

                const y =
                    path.y +
                    path.h *
                        (
                            yIndex +
                            0.5
                        ) /
                        sampleCount;

                if (
                    isMapCellExplored(
                        state.area,
                        x,
                        y
                    )
                ) {
                    return true;
                }
            }
        }

        return false;
    }


    /* ============================================================
       HUD
       ============================================================ */

    function drawHUD(
        ctx
    ) {
        const player =
            state.player;

        if (
            !player ||
            !state.running
        ) {
            return;
        }

        drawPlayerHUD(
            ctx,
            player
        );

        drawSkillHUD(
            ctx,
            player
        );

        drawBossHUD(
            ctx
        );

        drawInteractionHUD(
            ctx
        );

        drawHoldHUD(
            ctx
        );

        drawNotifications(
            ctx
        );

        drawMinimap(
            ctx
        );

        drawQuestTracker(
            ctx,
            player
        );
    }


    function drawPlayerHUD(
        ctx,
        player
    ) {
        const x =
            22;

        const y =
            22;

        const width =
            280;

        const character =
            getCharacterById(
                player.characterId
            ) ||
            currentCharacter();

        ctx.save();

        ctx.fillStyle =
            "rgba(14,13,17,0.82)";

        roundRectPath(
            ctx,
            x,
            y,
            width,
            105,
            12
        );

        ctx.fill();

        ctx.strokeStyle =
            "rgba(181,161,116,0.25)";

        ctx.lineWidth =
            1.5;

        ctx.stroke();

        ctx.fillStyle =
            "#ddd0b4";

        ctx.font =
            "700 13px serif";

        ctx.textAlign =
            "left";

        ctx.fillText(
            player.name ||
                character.name,
            x +
                14,
            y +
                19
        );

        ctx.font =
            "10px serif";

        ctx.fillStyle =
            "rgba(190,180,163,0.76)";

        ctx.fillText(
            `NÍVEL ${player.level}`,
            x +
                14,
            y +
                34
        );

        drawHUDBar(
            ctx,
            x +
                14,
            y +
                43,
            width -
                28,
            13,
            player.hp,
            player.maxHp,
            "#914e55",
            "VIDA"
        );

        drawHUDBar(
            ctx,
            x +
                14,
            y +
                63,
            width -
                28,
            11,
            player.energy,
            player.maxEnergy,
            "#597ea0",
            "ENERGIA"
        );

        drawHUDBar(
            ctx,
            x +
                14,
            y +
                81,
            width -
                28,
            9,
            player.exhaustion,
            player.maxExhaustion,
            "#a77f55",
            "EXAUSTÃO",
            true
        );

        /*
            XP.
        */
        const required =
            typeof V.getXPRequiredForLevel ===
            "function"
                ? V.getXPRequiredForLevel(
                    player.level
                )
                : Math.max(
                    1,
                    player.xp +
                        1
                );

        drawHUDBar(
            ctx,
            x +
                14,
            y +
                96,
            width -
                28,
            4,
            player.xp,
            required,
            "#8d729a",
            "",
            false,
            false
        );

        ctx.restore();
    }


    function drawHUDBar(
        ctx,
        x,
        y,
        w,
        h,
        value,
        max,
        color,
        label,
        reverse = false,
        showText = true
    ) {
        const ratio =
            clamp(
                finiteNumber(
                    value,
                    0
                ) /
                Math.max(
                    1,
                    finiteNumber(
                        max,
                        1
                    )
                ),
                0,
                1
            );

        ctx.fillStyle =
            "rgba(0,0,0,0.48)";

        roundRectPath(
            ctx,
            x,
            y,
            w,
            h,
            h /
                2
        );

        ctx.fill();

        const fill =
            reverse
                ? ratio
                : ratio;

        ctx.fillStyle =
            color;

        roundRectPath(
            ctx,
            x,
            y,
            w *
                fill,
            h,
            h /
                2
        );

        ctx.fill();

        if (
            showText &&
            label
        ) {
            ctx.font =
                "600 8px sans-serif";

            ctx.textAlign =
                "left";

            ctx.fillStyle =
                "rgba(245,239,226,0.88)";

            ctx.fillText(
                label,
                x +
                    4,
                y +
                    h -
                    3
            );

            ctx.textAlign =
                "right";

            ctx.fillText(
                `${Math.ceil(value)}/${Math.ceil(max)}`,
                x +
                    w -
                    4,
                y +
                    h -
                    3
            );
        }
    }


    /* ============================================================
       HABILIDADES
       ============================================================ */

    function drawSkillHUD(
        ctx,
        player
    ) {
        const width =
            230;

        const x =
            renderRuntime.width /
                2 -
                width /
                    2;

        const y =
            renderRuntime.height -
                72;

        ctx.save();

        ctx.fillStyle =
            "rgba(14,13,17,0.78)";

        roundRectPath(
            ctx,
            x,
            y,
            width,
            50,
            12
        );

        ctx.fill();

        const buttons = [
            {
                key:
                    "Q",
                skill:
                    "q",
                unlocked:
                    true
            },

            {
                key:
                    "R",
                skill:
                    "r",
                unlocked:
                    player.level >=
                    5
            },

            {
                key:
                    "F",
                skill:
                    "f",
                unlocked:
                    player.level >=
                    10
            },

            {
                key:
                    "ESPAÇO",
                skill:
                    "dash",
                unlocked:
                    getDashVersion(
                        player
                    ) >
                    0
            }
        ];

        let bx =
            x +
                10;

        for (
            const button of
            buttons
        ) {
            const bw =
                button.skill ===
                "dash"
                    ? 65
                    : 42;

            drawSkillButton(
                ctx,
                bx,
                y +
                    7,
                bw,
                36,
                button,
                player
            );

            bx +=
                bw +
                7;
        }

        ctx.restore();
    }


    function drawSkillButton(
        ctx,
        x,
        y,
        w,
        h,
        button,
        player
    ) {
        let cooldown =
            0;

        if (
            button.skill ===
            "dash"
        ) {
            cooldown =
                finiteNumber(
                    player
                        .universalDashCooldown,
                    0
                );
        } else {
            cooldown =
                finiteNumber(
                    player
                        .skillCooldowns[
                            button.skill
                        ],
                    0
                );
        }

        ctx.fillStyle =
            button.unlocked
                ? "rgba(64,59,70,0.9)"
                : "rgba(31,30,34,0.9)";

        roundRectPath(
            ctx,
            x,
            y,
            w,
            h,
            7
        );

        ctx.fill();

        ctx.strokeStyle =
            button.unlocked
                ? "rgba(182,165,129,0.32)"
                : "rgba(120,115,110,0.22)";

        ctx.lineWidth =
            1;

        ctx.stroke();

        if (
            cooldown >
            0
        ) {
            ctx.fillStyle =
                "rgba(0,0,0,0.58)";

            roundRectPath(
                ctx,
                x,
                y,
                w,
                h,
                7
            );

            ctx.fill();
        }

        ctx.textAlign =
            "center";

        ctx.font =
            button.skill ===
            "dash"
                ? "700 8px sans-serif"
                : "700 12px sans-serif";

        ctx.fillStyle =
            button.unlocked
                ? "#ddd0b5"
                : "#68635c";

        ctx.fillText(
            button.key,
            x +
                w /
                    2,
            y +
                15
        );

        ctx.font =
            "9px sans-serif";

        if (
            !button.unlocked
        ) {
            ctx.fillStyle =
                "#736d66";

            ctx.fillText(
                button.skill ===
                    "r"
                    ? "NV.5"
                    : button.skill ===
                        "f"
                        ? "NV.10"
                        : "BLOQ.",

                x +
                    w /
                        2,

                y +
                    29
            );
        } else if (
            cooldown >
            0
        ) {
            ctx.fillStyle =
                "#c8bba2";

            ctx.fillText(
                cooldown.toFixed(
                    1
                ),

                x +
                    w /
                        2,

                y +
                    29
            );
        } else {
            ctx.fillStyle =
                "#918571";

            ctx.fillText(
                button.skill ===
                    "dash"
                    ? getDashVersion(
                        player
                    ) ===
                        2
                        ? "V2"
                        : "V1"
                    : "",

                x +
                    w /
                        2,

                y +
                    29
            );
        }
    }


    /* ============================================================
       BOSS HUD
       ============================================================ */

    function drawBossHUD(
        ctx
    ) {
        const boss =
            state.bossBarTarget;

        if (
            !boss ||
            boss.dead
        ) {
            return;
        }

        const width =
            Math.min(
                520,
                renderRuntime.width *
                    0.46
            );

        const x =
            renderRuntime.width /
                2 -
            width /
                2;

        const y =
            24;

        const ratio =
            clamp(
                boss.hp /
                    boss.maxHp,
                0,
                1
            );

        ctx.save();

        ctx.textAlign =
            "center";

        ctx.font =
            "700 13px serif";

        ctx.fillStyle =
            "#ded2bc";

        ctx.fillText(
            boss.name ||
                "BOSS",
            renderRuntime.width /
                2,
            y
        );

        ctx.fillStyle =
            "rgba(0,0,0,0.65)";

        roundRectPath(
            ctx,
            x,
            y +
                10,
            width,
            14,
            7
        );

        ctx.fill();

        const color =
            boss.id ===
                "monarch"
                ? "#68526f"
                : boss.id ===
                    "vaelkor"
                    ? "#664779"
                    : "#874e55";

        ctx.fillStyle =
            color;

        roundRectPath(
            ctx,
            x,
            y +
                10,
            width *
                ratio,
            14,
            7
        );

        ctx.fill();

        if (
            boss.id ===
            "monarch"
        ) {
            drawMonarchStaggerCracksHUD(
                ctx,
                boss,
                x,
                y +
                    32,
                width
            );
        }

        ctx.restore();
    }


    function drawMonarchStaggerCracksHUD(
        ctx,
        boss,
        x,
        y,
        width
    ) {
        const threshold =
            boss.definition
                ?.stagger
                ?.threshold ||
            15;

        const ratio =
            clamp(
                finiteNumber(
                    boss.stagger,
                    0
                ) /
                threshold,
                0,
                1
            );

        /*
            Não mostra número 14/15.
            Só rachaduras ficando fortes.
        */
        const segments =
            8;

        for (
            let index = 0;
            index < segments;
            index += 1
        ) {
            const active =
                index /
                    segments <
                ratio;

            const sx =
                x +
                width *
                (
                    index +
                    0.5
                ) /
                segments;

            ctx.strokeStyle =
                active
                    ? "rgba(220,218,224,0.76)"
                    : "rgba(120,112,125,0.16)";

            ctx.lineWidth =
                active
                    ? 2
                    : 1;

            ctx.beginPath();

            ctx.moveTo(
                sx -
                    7,
                y
            );

            ctx.lineTo(
                sx -
                    1,
                y +
                    5
            );

            ctx.lineTo(
                sx -
                    4,
                y +
                    11
            );

            ctx.lineTo(
                sx +
                    6,
                y +
                    17
            );

            ctx.stroke();
        }
    }


