    /* ============================================================
       TRANSIÇÕES
       ============================================================ */

    function drawTransitionOverlay(
        ctx
    ) {
        const transition =
            state.transition;

        if (!transition) {
            return;
        }

        const duration =
            Math.max(
                0.01,
                finiteNumber(
                    transition.duration,
                    1
                )
            );

        const progress =
            clamp(
                finiteNumber(
                    transition.timer,
                    0
                ) /
                duration,
                0,
                1
            );

        let alpha;

        if (
            transition.type ===
            "rest"
        ) {
            alpha =
                Math.sin(
                    progress *
                    Math.PI
                ) *
                0.88;
        } else {
            alpha =
                progress <
                    0.5
                    ? progress *
                        2
                    : (
                        1 -
                        progress
                    ) *
                        2;
        }

        ctx.save();

        ctx.fillStyle =
            `rgba(5,4,7,${clamp(
                alpha,
                0,
                0.94
            )})`;

        ctx.fillRect(
            0,
            0,
            renderRuntime.width,
            renderRuntime.height
        );

        if (
            transition.title &&
            alpha >
                0.35
        ) {
            ctx.textAlign =
                "center";

            ctx.fillStyle =
                `rgba(220,210,192,${clamp(
                    alpha,
                    0,
                    1
                )})`;

            ctx.font =
                "700 22px serif";

            ctx.fillText(
                transition.title,
                renderRuntime.width /
                    2,
                renderRuntime.height /
                    2
            );
        }

        ctx.restore();
    }


